import { test } from "node:test";
import assert from "node:assert/strict";
import type { TestContext } from "node:test";
import {
  canonicalCeremonyPlan,
  digestCeremonyPlan,
  parseCeremonyPlan,
  preferredPath,
  requiredOf,
} from "../../src/core/ceremony-plan.js";
import {
  discoverCeremony,
  inferRole,
  type CeremonyClassifier,
} from "../../src/server/ceremony-discovery.js";
import type { PageSnapshot } from "../../src/core/browser-contracts.js";
import type { CeremonyPage } from "../../src/server/browser-driver.js";
import { startAuthProvider } from "../doubles/auth-provider/server.js";
import { createHttpCeremonyPage } from "../doubles/http-page.js";

/**
 * Discovery, read against the same provider doubles the ceremonies run on.
 *
 * The point of these is not that discovery produces a particular plan — page
 * shapes are randomized per instance, so a golden plan would be meaningless.
 * It is that the plan it produces says true things about the provider, and
 * that producing it changed nothing at the provider.
 */

async function provider(
  t: TestContext,
  behavior: Parameters<typeof startAuthProvider>[0] = {},
) {
  const double = await startAuthProvider({ seed: 7, ...behavior });
  t.after(() => double.close());
  return double;
}

const discover = (double: { origin: string }, path: string, goal = "sign-in") =>
  discoverCeremony({
    page: createHttpCeremonyPage(),
    entryUrl: `${double.origin}${path}`,
    goal: goal as "sign-in",
    allowedOrigins: [double.origin],
  });

test("discovery names the data a sign-in actually asks for", async (t) => {
  const double = await provider(t);
  const { plan } = await discover(double, "/signin");
  const roles = Object.values(plan.data).map((datum) => datum.role);
  assert.ok(roles.includes("username"), `saw roles: ${roles.join(", ")}`);
  assert.ok(roles.includes("password"), `saw roles: ${roles.join(", ")}`);
  // A password is a credential wherever it is found.
  const password = Object.values(plan.data).find(
    (datum) => datum.role === "password",
  );
  assert.equal(password?.secret, true);
  assert.deepEqual(password?.source, { from: "caller" });
});

test("discovery changes nothing at the provider", async (t) => {
  // The property that makes it safe to point at somebody else's service: it
  // reads pages and follows links, and never submits anything.
  const double = await provider(t, { verification: "code" });
  const before = double.accounts().length;
  await discover(double, `${double.signupPath}`, "registration");
  await discover(double, "/signin");
  assert.equal(double.accounts().length, before, "no account was created");
  assert.deepEqual(double.mailbox.messages(), [], "no mail was sent");
  assert.deepEqual(double.issuedTokens(), [], "no credential was issued");
  assert.deepEqual(double.installed(), []);
  assert.deepEqual(double.authenticatedBasic(), []);
});

test("a registration form is read as the data a caller must bring", async (t) => {
  const double = await provider(t, { verification: "code" });
  const { plan } = await discover(double, double.signupPath, "registration");
  const roles = Object.values(plan.data).map((datum) => datum.role);
  assert.ok(roles.includes("email"), `saw roles: ${roles.join(", ")}`);
  assert.ok(roles.includes("password"), `saw roles: ${roles.join(", ")}`);
  const path = preferredPath(plan);
  const required = requiredOf(plan, path).map((datum) => datum.role);
  // Everything the caller is told to bring is something they could hold. A
  // code the provider has not sent yet is never on this list.
  assert.ok(!required.includes("verification-code"));
});

/**
 * A page the double cannot serve to a reader who has not signed in. The port
 * exists to be substituted, and substituting it is the only honest way to test
 * how a shape like this is read — the alternative was a test that returned
 * early and asserted nothing.
 */
function scriptedPage(
  pages: Record<
    string,
    { snapshot: PageSnapshot; links?: Record<number, string> }
  >,
  start: string,
): CeremonyPage {
  let current = start;
  return {
    url: async () => current,
    goto: async (target) => {
      current = target;
    },
    settle: async () => {},
    snapshot: async () => pages[current]!.snapshot,
    click: async (element) => {
      current = pages[current]?.links?.[element.index] ?? current;
    },
    fill: async () => {
      throw new Error("Discovery must never fill a field");
    },
    check: async () => {
      throw new Error("Discovery must never check a box");
    },
  };
}

const page = (
  path: string,
  elements: PageSnapshot["elements"],
  extra: Partial<PageSnapshot> = {},
): PageSnapshot => ({
  path,
  title: "",
  headings: ["Confirm your address"],
  alerts: [],
  challenge: false,
  passkey: false,
  elements,
  ...extra,
});

test("a code field is attributed to the step that delivers it", async () => {
  // Discovery never triggered a send, so it cannot have observed delivery. It
  // names the step anyway, because the plan is unrunnable without it, and says
  // in `uncertain` that this part was inferred rather than seen.
  const origin = "https://provider.test";
  const { plan, uncertain } = await discoverCeremony({
    page: scriptedPage(
      {
        [`${origin}/confirm`]: {
          snapshot: page(`${origin}/confirm`, [
            {
              index: 0,
              kind: "input",
              type: "text",
              label: "Confirmation code",
            },
            { index: 1, kind: "button", text: "Confirm" },
          ]),
        },
      },
      `${origin}/confirm`,
    ),
    entryUrl: `${origin}/confirm`,
    goal: "registration",
    allowedOrigins: [origin],
  });

  const entries = Object.entries(plan.data);
  assert.equal(entries.length, 1);
  const [key, datum] = entries[0]!;
  assert.equal(datum.role, "verification-code");
  assert.equal(datum.secret, true);
  assert.equal(datum.source.from, "step");

  const producer = plan.steps.find(
    (step) => datum.source.from === "step" && step.id === datum.source.step,
  );
  assert.ok(producer, "the delivering step must be in the plan");
  assert.equal(producer.kind, "out-of-band");
  assert.deepEqual(producer.produces, [key]);

  // It must run before the page that asks for it, on every path.
  for (const path of plan.paths) {
    const delivery = path.steps.indexOf(producer.id);
    const asks = path.steps.findIndex((id) =>
      plan.steps.find((step) => step.id === id)?.uses.includes(key),
    );
    assert.ok(
      delivery >= 0 && delivery < asks,
      `${path.id} runs them in order`,
    );
  }

  // The caller is never told to bring a code that has not been sent.
  assert.deepEqual(requiredOf(plan, preferredPath(plan)), []);
  assert.ok(
    uncertain.some((line) => /arrives out of band/.test(line)),
    `an inferred delivery must be declared uncertain; got ${JSON.stringify(uncertain)}`,
  );
});

test("discovery refuses to act, even when a page invites it", async () => {
  // The scripted page throws if a field is filled or a box checked. Reaching
  // the end of discovery at all is the assertion.
  const origin = "https://provider.test";
  const { plan } = await discoverCeremony({
    page: scriptedPage(
      {
        [`${origin}/signin`]: {
          snapshot: page(`${origin}/signin`, [
            { index: 0, kind: "input", type: "text", label: "Login name" },
            { index: 1, kind: "input", type: "password", label: "Password" },
            { index: 2, kind: "checkbox", label: "Remember me" },
            { index: 3, kind: "button", text: "Sign in" },
          ]),
        },
      },
      `${origin}/signin`,
    ),
    entryUrl: `${origin}/signin`,
    goal: "sign-in",
    allowedOrigins: [origin],
  });
  assert.deepEqual(
    Object.values(plan.data)
      .map((datum) => datum.role)
      .sort(),
    ["password", "username"],
  );
});

test("a link that only appears once is reported, not silently dropped", async () => {
  // Replay is how a branch is reached, so a link that is not there the second
  // time means a branch went unexplored. Saying so is the difference between a
  // partial map and a wrong one.
  const origin = "https://provider.test";
  let seen = 0;
  const base = page(`${origin}/signin`, [
    { index: 0, kind: "input", type: "text", label: "Login name" },
    { index: 1, kind: "link", text: "Create an account" },
  ]);
  const { uncertain } = await discoverCeremony({
    page: {
      url: async () => `${origin}/signin`,
      goto: async () => {},
      settle: async () => {},
      // The link is gone by the time the branch is replayed.
      snapshot: async () =>
        seen++ === 0 ? base : { ...base, elements: [base.elements[0]!] },
      click: async () => {},
      fill: async () => {
        throw new Error("Discovery must never fill a field");
      },
      check: async () => {
        throw new Error("Discovery must never check a box");
      },
    },
    entryUrl: `${origin}/signin`,
    goal: "sign-in",
    allowedOrigins: [origin],
  });
  assert.ok(
    uncertain.some((line) => /was not on the page the second time/.test(line)),
    `an unexplored branch must be reported; got ${JSON.stringify(uncertain)}`,
  );
});

test("a page that demands a person is a human step with a stated reason", async (t) => {
  const double = await provider(t, {
    challengeAt: "sign-in",
    challengeClearable: true,
  });
  const { plan } = await discover(double, "/signin");
  const human = plan.steps.filter((step) => step.kind === "human");
  assert.equal(human.length, 1, "the challenge is the one human step");
  assert.equal(human[0]?.humanReason, "challenge");
  // And the path says what it costs, which is what a caller chooses on.
  assert.ok(preferredPath(plan).handoffs >= 1);
});

test("a passkey prompt with nothing to type is a human step, a hint is not", async (t) => {
  const only = await provider(t, { passkeyOnly: true });
  const prompt = await discover(only, "/signin");
  assert.deepEqual(
    prompt.plan.steps
      .filter((step) => step.kind === "human")
      .map((step) => step.humanReason),
    ["passkey"],
  );

  // Conditional UI still accepts a password, so nobody has to be interrupted.
  const hinted = await provider(t, { conditionalPasskey: true });
  const conditional = await discover(hinted, "/signin");
  assert.deepEqual(
    conditional.plan.steps.filter((step) => step.kind === "human"),
    [],
  );
  assert.equal(preferredPath(conditional.plan).handoffs, 0);
});

test("a sign-in offering registration is discovered as two ways through", async (t) => {
  const double = await provider(t, { verification: "none" });
  const { plan } = await discover(double, "/signin");
  // The fork is the point: the same goal, reached more than one way.
  assert.ok(
    plan.paths.length >= 2,
    `expected a fork, got paths: ${plan.paths.map((p) => p.id).join(", ")}`,
  );
  // Every path is runnable in the order it is written, and the entry page is
  // on all of them — both enforced by the schema, which the plan passed.
  for (const path of plan.paths) assert.ok(path.steps.length >= 1);
  const entry = plan.paths[0]!.steps[0];
  assert.ok(plan.paths.every((path) => path.steps[0] === entry));
});

test("a provider that redirects says so, and discovery records why", async (t) => {
  // `/authorize` sends an unauthenticated visitor to sign in first. That is a
  // prerequisite the provider states for free, and it is observable without
  // submitting anything.
  const double = await provider(t);
  const { plan, uncertain, visited } = await discover(
    double,
    "/authorize",
    "authorize",
  );
  assert.ok(
    visited.some((path) => path.endsWith("/signin")),
    `discovery should have landed on sign-in; visited ${visited.join(", ")}`,
  );
  assert.ok(
    uncertain.some((line) => /redirected to/.test(line)),
    `the redirect should be recorded; got ${JSON.stringify(uncertain)}`,
  );
  assert.equal(plan.goal, "authorize");
});

test("a discovered plan is shareable and comes back identical", async (t) => {
  const double = await provider(t);
  const { plan } = await discover(double, "/signin");
  const text = canonicalCeremonyPlan(plan);
  const reloaded = parseCeremonyPlan(text);
  assert.equal(canonicalCeremonyPlan(reloaded), text);
  assert.equal(
    await digestCeremonyPlan(reloaded),
    await digestCeremonyPlan(plan),
  );
  // A plan carries shape and order, never a value. The schema is strict, so
  // there is no field a value could live in; what is worth checking is that
  // nothing was smuggled into the free text that comes off the provider's own
  // pages.
  const freeText = [
    plan.title,
    ...plan.steps.map((step) => step.label),
    ...plan.paths.flatMap((path) => [path.label, ...path.when]),
  ].join(" ");
  for (const forbidden of ["@", "password=", "token", "cookie", "Bearer"])
    assert.ok(
      !freeText.includes(forbidden),
      `free text must not carry "${forbidden}": ${freeText}`,
    );
  // And every datum is exactly the four fields the schema allows, so a value
  // has nowhere to hide even if discovery tried.
  for (const datum of Object.values(plan.data))
    assert.deepEqual(Object.keys(datum).sort(), [
      "always",
      "role",
      "secret",
      "source",
    ]);
});

test("discovery stops at the origins it was allowed to read", async (t) => {
  const double = await provider(t);
  const result = await discoverCeremony({
    page: createHttpCeremonyPage(),
    entryUrl: `${double.origin}/signin`,
    goal: "sign-in",
    // Deliberately empty: nothing is permitted, including the entry page.
    allowedOrigins: ["https://elsewhere.invalid"],
  }).catch((error: Error) => error);
  assert.ok(result instanceof Error, "reading nothing must not yield a plan");
  assert.match(result.message, /no page it was permitted to read/);
});

test("a classifier may refine a page's kind but never invents its data", async (t) => {
  const double = await provider(t);
  const seen: string[] = [];
  const classifier: CeremonyClassifier = async ({ snapshot }) => {
    seen.push(snapshot.path);
    return { kind: "decision", label: "Named by inference" };
  };
  const { plan } = await discoverCeremony({
    page: createHttpCeremonyPage(),
    entryUrl: `${double.origin}/signin`,
    goal: "sign-in",
    allowedOrigins: [double.origin],
    classifier,
  });
  assert.ok(seen.length > 0, "the classifier was consulted");
  assert.ok(plan.steps.some((step) => step.label === "Named by inference"));
  // The roles still come from the page, not from the model.
  const roles = Object.values(plan.data).map((datum) => datum.role);
  assert.ok(roles.includes("password"));
});

test("a classifier that fails or refuses leaves discovery working", async (t) => {
  // Inference is optional. A plan that only exists when a model answers is not
  // a plan anyone can rely on.
  const double = await provider(t);
  const { plan } = await discoverCeremony({
    page: createHttpCeremonyPage(),
    entryUrl: `${double.origin}/signin`,
    goal: "sign-in",
    allowedOrigins: [double.origin],
    classifier: async () => {
      throw new Error("model unavailable");
    },
  });
  const roles = Object.values(plan.data).map((datum) => datum.role);
  assert.ok(roles.includes("password"));
  assert.ok(plan.steps.length >= 1);
});

test("role inference survives page shapes it has never seen", async (t) => {
  // The provider regenerates field names, labels, wording and control order per
  // instance. A reader that passes on one shape and fails on the next has
  // memorised a page rather than understood it — which is exactly how the
  // confirmation-box rule was found to be wrong.
  const wrong: string[] = [];
  for (let seed = 1; seed <= 25; seed++) {
    const double = await startAuthProvider({ seed, verification: "code" });
    t.after(() => double.close());
    const { plan } = await discoverCeremony({
      page: createHttpCeremonyPage(),
      entryUrl: `${double.origin}${double.signupPath}`,
      goal: "registration",
      allowedOrigins: [double.origin],
    });
    const roles = new Set(Object.values(plan.data).map((datum) => datum.role));
    const missing = (["password", "password-confirm", "email"] as const).filter(
      (role) => !roles.has(role),
    );
    if (missing.length > 0)
      wrong.push(`seed ${seed} missed ${missing.join(", ")}`);
  }
  assert.deepEqual(wrong, []);
});

test("field roles are read from the control, not from its position", async (t) => {
  const page = [
    { index: 0, kind: "input", type: "text", label: "Username" },
    { index: 1, kind: "input", type: "password", label: "Password" },
    { index: 2, kind: "input", type: "password", label: "Confirm password" },
    { index: 3, kind: "input", type: "email", label: "Work address" },
    { index: 4, kind: "input", type: "text", label: "Confirmation code" },
    { index: 5, kind: "input", type: "text", label: "Authenticator code" },
    { index: 6, kind: "input", type: "date", label: "Date of birth" },
    { index: 7, kind: "button", text: "Continue" },
    { index: 8, kind: "link", text: "Create an account" },
  ] as const;
  const roles = page.map((element) =>
    inferRole(element as never, page as never),
  );
  assert.deepEqual(roles, [
    "username",
    "password",
    "password-confirm",
    "email",
    "verification-code",
    "totp-code",
    "birth-date",
    undefined,
    undefined,
  ]);
  void t;
});

import { z } from "zod";
import { ceremonyGoalSchema, ceremonyRoleSchema } from "./browser-contracts.js";
import { identifierSchema } from "./operation-contracts.js";

/**
 * A ceremony plan: what it takes to get through a provider's authentication,
 * written down so it can be shared and run again.
 *
 * A plan is a template, not a record of an attempt. It names the steps, what
 * each one needs before it can run, which data the caller has to be able to
 * supply, and the different ways the goal can be reached — because there is
 * usually more than one, and they do not cost the same. What a plan never
 * carries is a value, a credential, a session, or a line of the provider's
 * markup: it describes shape and order, so sharing one discloses nothing about
 * the person or the attempt it came from.
 *
 * The four questions a plan exists to answer:
 *
 * - **What must happen first?** `step.needs` — a registration before a sign-in,
 *   a sign-in before a consent.
 * - **What else would work?** `paths` — more than one route to the same goal,
 *   each with the price it charges in human attention.
 * - **What do I have to be able to supply?** `data` — every role any path may
 *   ask for, and whether the caller brings it, an earlier step produces it, or
 *   only a person can.
 * - **Is this the same plan I had before?** `canonicalCeremonyPlan` and
 *   `digestCeremonyPlan`.
 */

export const PLAN_LIMITS = Object.freeze({
  bytes: 128 * 1024,
  steps: 48,
  paths: 12,
  data: 32,
});

/** Where a datum comes from, which decides who has to be asked for it. */
export const dataSourceSchema = z.discriminatedUnion("from", [
  /** The caller must hold this before the ceremony starts. */
  z.strictObject({ from: z.literal("caller") }),
  /** An earlier step produces it, such as a code mailed during registration. */
  z.strictObject({ from: z.literal("step"), step: identifierSchema }),
  /**
   * Only a person can supply it, in their own browser. A plan that needs one
   * of these is a plan that cannot run unattended, and says so here rather
   * than discovering it halfway through.
   */
  z.strictObject({ from: z.literal("human") }),
]);
export type DataSource = z.infer<typeof dataSourceSchema>;

export const planDatumSchema = z
  .strictObject({
    role: ceremonyRoleSchema,
    /** Whether disclosing it would disclose a credential. */
    secret: z.boolean(),
    source: dataSourceSchema,
    /** False when only some paths ask for it. */
    always: z.boolean(),
  })
  .strict();
export type PlanDatum = z.infer<typeof planDatumSchema>;

/**
 * What a step is. These are kinds of obstacle, not provider names: the point
 * is that a reader can tell whether a step is something an agent can do.
 */
export const planStepKinds = [
  /** Fill a form and submit it. */
  "form",
  /** Follow a link or button that only moves the ceremony along. */
  "navigate",
  /** Approve or refuse something on the provider's behalf. */
  "decision",
  /** Read a code or link out of a mailbox. */
  "out-of-band",
  /** A human challenge: a widget, an authenticator, a browser dialog. */
  "human",
  /** Redirect back to the caller with a result. */
  "callback",
] as const;
export const planStepKindSchema = z.enum(planStepKinds);
export type PlanStepKind = z.infer<typeof planStepKindSchema>;

export const planStepSchema = z
  .strictObject({
    id: identifierSchema,
    kind: planStepKindSchema,
    /** A short description for a person reading the plan. */
    label: z.string().min(1).max(120),
    /**
     * Origin and path only, never a query string: a plan is a template, and a
     * query carries the particular attempt it was discovered on.
     */
    at: z.string().url().max(512).optional(),
    /** Steps that must have run first. */
    needs: z.array(identifierSchema).max(PLAN_LIMITS.steps),
    /** Data this step consumes, by key into `data`. */
    uses: z.array(identifierSchema).max(PLAN_LIMITS.data),
    /** Data this step produces, by key into `data`. */
    produces: z.array(identifierSchema).max(PLAN_LIMITS.data),
    /**
     * Why a person is needed, when they are. Present exactly on `human` steps
     * so a reader never has to guess what the interruption is for.
     */
    humanReason: z
      .enum(["challenge", "passkey", "native-dialog", "approval"])
      .optional(),
  })
  .strict()
  .superRefine((step, context) => {
    const human = step.kind === "human";
    if (human !== (step.humanReason !== undefined))
      context.addIssue({
        code: "custom",
        message:
          "A human step states its reason, and only a human step has one",
      });
  });
export type PlanStep = z.infer<typeof planStepSchema>;

/**
 * One way through. Paths are what make a fork legible: the same goal reached
 * by a signed request or by a person clearing an interstitial is two paths,
 * and `handoffs` is the difference that matters when choosing between them.
 */
export const planPathSchema = z
  .strictObject({
    id: identifierSchema,
    label: z.string().min(1).max(120),
    steps: z.array(identifierSchema).min(1).max(PLAN_LIMITS.steps),
    /** How many times this path has to interrupt a person. */
    handoffs: z.number().int().min(0).max(PLAN_LIMITS.steps),
    /** Preconditions that make this path the applicable one. */
    when: z.array(z.string().min(1).max(120)).max(8),
  })
  .strict();
export type PlanPath = z.infer<typeof planPathSchema>;

export const ceremonyPlanSchema = z
  .object({
    schemaVersion: z.literal(1),
    id: identifierSchema,
    title: z.string().min(1).max(120),
    goal: ceremonyGoalSchema,
    /**
     * The origin this plan was written against. A plan is reusable against the
     * same provider, not evidence about it, and never a claim that the
     * provider endorses it.
     */
    origin: z.string().url().max(512),
    data: z
      .record(identifierSchema, planDatumSchema)
      .refine((value) => Object.keys(value).length <= PLAN_LIMITS.data),
    steps: z.array(planStepSchema).min(1).max(PLAN_LIMITS.steps),
    paths: z.array(planPathSchema).min(1).max(PLAN_LIMITS.paths),
  })
  .strict()
  .superRefine((plan, context) => {
    const issue = (message: string) =>
      context.addIssue({ code: "custom", message });
    const steps = new Map(plan.steps.map((step) => [step.id, step]));
    if (steps.size !== plan.steps.length) issue("Duplicate step");

    for (const step of plan.steps) {
      for (const need of step.needs)
        if (!steps.has(need)) issue(`Unknown prerequisite ${need}`);
      for (const key of [...step.uses, ...step.produces])
        if (!Object.hasOwn(plan.data, key)) issue(`Unknown datum ${key}`);
      // A step cannot consume what it is itself producing.
      for (const key of step.produces)
        if (step.uses.includes(key)) issue(`${key} is both used and produced`);
    }

    // Every datum a step produces must say so, and the other way round: a plan
    // whose data and steps disagree would send a caller looking for a value
    // nothing creates.
    for (const [key, datum] of Object.entries(plan.data)) {
      if (datum.source.from !== "step") continue;
      const producer = steps.get(datum.source.step);
      if (!producer) issue(`${key} names a step that is not in the plan`);
      else if (!producer.produces.includes(key))
        issue(`${key} claims a producer that does not produce it`);
    }

    for (const path of plan.paths) {
      const seen = new Set<string>();
      for (const id of path.steps) {
        const step = steps.get(id);
        if (!step) {
          issue(`Path ${path.id} names unknown step ${id}`);
          continue;
        }
        // A path must be runnable in the order it is written: every
        // prerequisite of a step has to appear before it on that same path.
        for (const need of step.needs)
          if (!seen.has(need))
            issue(`Path ${path.id} runs ${id} before ${need}`);
        seen.add(id);
      }
      const human = path.steps.filter(
        (id) => steps.get(id)?.kind === "human",
      ).length;
      if (human !== path.handoffs)
        issue(
          `Path ${path.id} claims ${path.handoffs} handoffs but has ${human}`,
        );
    }

    // A step no path uses is not part of the plan; leaving it in would make
    // the plan look like it does more than it does.
    const used = new Set(plan.paths.flatMap((path) => path.steps));
    for (const step of plan.steps)
      if (!used.has(step.id)) issue(`No path uses ${step.id}`);

    // `always` has to mean what it says, or a caller cannot tell which data it
    // must have before starting.
    for (const [key, datum] of Object.entries(plan.data)) {
      const paths = plan.paths.filter((path) =>
        path.steps.some((id) => steps.get(id)?.uses.includes(key)),
      );
      if (paths.length === 0) issue(`No path uses ${key}`);
      else if (datum.always !== (paths.length === plan.paths.length))
        issue(
          `${key} is marked always=${datum.always} but is used by ${paths.length} of ${plan.paths.length} paths`,
        );
    }
  });
export type CeremonyPlan = z.infer<typeof ceremonyPlanSchema>;

export function parseCeremonyPlan(text: string): CeremonyPlan {
  if (new TextEncoder().encode(text).byteLength > PLAN_LIMITS.bytes)
    throw new Error("Ceremony plan exceeds import limit");
  return ceremonyPlanSchema.parse(JSON.parse(text));
}

/** Stable bytes for a plan, so two copies can be compared or addressed. */
export function canonicalCeremonyPlan(plan: unknown): string {
  const parsed = ceremonyPlanSchema.parse(plan);
  function canonical(value: unknown): unknown {
    if (Array.isArray(value)) return value.map(canonical);
    if (value !== null && typeof value === "object")
      return Object.fromEntries(
        Object.entries(value)
          .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
          .map(([key, item]) => [key, canonical(item)]),
      );
    return value;
  }
  return JSON.stringify(canonical(parsed));
}

/**
 * Integrity only. A digest says two plans are the same bytes; it conveys no
 * authority, no provider endorsement and no evidence that the plan works.
 */
export async function digestCeremonyPlan(plan: unknown): Promise<string> {
  const digest = await globalThis.crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(canonicalCeremonyPlan(plan)),
  );
  return Buffer.from(digest).toString("base64url");
}

/**
 * The path to try first: the one that interrupts a person least, and among
 * equals the shortest. This is the whole point of recording alternatives —
 * a caller should not have to decide what "cheapest" means.
 */
export function preferredPath(plan: CeremonyPlan): PlanPath {
  return [...plan.paths].sort(
    (a, b) =>
      a.handoffs - b.handoffs ||
      a.steps.length - b.steps.length ||
      (a.id < b.id ? -1 : 1),
  )[0]!;
}

/**
 * Data the caller must be able to supply for a path, in the order the path
 * asks for it. Data an earlier step produces is excluded: the caller does not
 * bring a code that has not been sent yet.
 */
export function requiredOf(
  plan: CeremonyPlan,
  path: PlanPath,
): readonly (PlanDatum & { key: string })[] {
  const steps = new Map(plan.steps.map((step) => [step.id, step]));
  const seen = new Set<string>();
  const needed: (PlanDatum & { key: string })[] = [];
  for (const id of path.steps)
    for (const key of steps.get(id)?.uses ?? []) {
      const datum = plan.data[key];
      if (!datum || seen.has(key) || datum.source.from !== "caller") continue;
      seen.add(key);
      needed.push({ ...datum, key });
    }
  return needed;
}

import {
  type CeremonyGoal,
  type CeremonyRole,
  type PageSnapshot,
  type SnapshotElement,
} from "../core/browser-contracts.js";
import {
  ceremonyPlanSchema,
  PLAN_LIMITS,
  type CeremonyPlan,
  type PlanDatum,
  type PlanPath,
  type PlanStep,
} from "../core/ceremony-plan.js";
import type { CeremonyPage } from "./browser-driver.js";

/**
 * Work out what a provider's authentication actually requires, by reading it.
 *
 * **Discovery reads; it does not act.** It navigates and follows links, and it
 * never fills a field or presses a submit button. That is the property that
 * makes it safe to point at a provider you do not own: it cannot consume an
 * address, create an account, trip a rate limiter or spend a one-time code.
 * Everything it reports was visible on a page that a visitor could have loaded.
 *
 * What it produces is a `CeremonyPlan` — the steps, what each needs first, the
 * data a caller has to be able to supply, and the different ways through. What
 * it cannot settle by reading, it says so in `uncertain` rather than guessing,
 * because a plan that looks confident about something nobody checked is worse
 * than one that admits the gap.
 */

/** A model may name a page discovery's own rules cannot. It is never required. */
export type PageClassification = {
  kind: PlanStep["kind"];
  label: string;
  humanReason?: PlanStep["humanReason"];
};
export type CeremonyClassifier = (input: {
  goal: CeremonyGoal;
  snapshot: PageSnapshot;
}) => Promise<PageClassification | undefined>;

export type DiscoveryOptions = {
  page: CeremonyPage;
  entryUrl: string;
  goal: CeremonyGoal;
  /** Origins discovery may read. It stops rather than leaving them. */
  allowedOrigins: readonly string[];
  /** Optional inference for a page the shape rules cannot name. */
  classifier?: CeremonyClassifier;
  /** Pages to load at most. Discovery is bounded, never exhaustive. */
  maxPages?: number;
  /** Links to follow deep at most, counted from the entry page. */
  maxDepth?: number;
  id?: string;
  title?: string;
};

export type DiscoveryResult = {
  plan: CeremonyPlan;
  /**
   * What reading alone could not settle. Each entry is a sentence a person can
   * act on, not a code.
   */
  uncertain: readonly string[];
  /** Pages actually loaded, in order, as origin+pathname. */
  visited: readonly string[];
};

/* -------------------------------------------------------------------------- */
/* Reading a page                                                             */
/* -------------------------------------------------------------------------- */

const rolePatterns = {
  confirmPassword: /confirm|repeat|again|verify your password/i,
  email: /e-?mail/i,
  identifier: /user\s?name|\blogin\b|\baccount\b|\bidentifier\b|\bhandle\b/i,
  displayName:
    /display name|your name|full name|application name|token name|key name/i,
  birthDate: /birth|birthday/i,
  verification: /confirmation code|verification code|digit code|\bcode\b/i,
  totp: /authenticator|two-factor|one-time|2fa/i,
  userCode: /device code|user code|code shown/i,
} as const;

const describe = (element: SnapshotElement) =>
  `${element.label ?? ""} ${element.placeholder ?? ""} ${element.name ?? ""}`;

/**
 * Name what a field is asking for.
 *
 * Discovery has to be able to say what a ceremony needs without a model in the
 * loop — a plan that only exists when inference is available is not a plan you
 * can rely on. A classifier can refine a page's kind, never rename its data.
 */
export function inferRole(
  element: SnapshotElement,
  page: readonly SnapshotElement[],
): CeremonyRole | undefined {
  if (element.kind !== "input" && element.kind !== "select") return undefined;
  const text = describe(element);
  if (element.type === "password") {
    if (rolePatterns.confirmPassword.test(text)) return "password-confirm";
    const passwords = page.filter((other) => other.type === "password");
    // Position decides only when nothing else does. A page is free to put the
    // confirmation box first, and then the other box is the password however
    // late it appears — reading the second box as the confirmation regardless
    // would make both of them the confirmation and neither the password.
    const named = passwords.some((other) =>
      rolePatterns.confirmPassword.test(describe(other)),
    );
    if (!named && passwords.length > 1 && passwords[1]?.index === element.index)
      return "password-confirm";
    return "password";
  }
  if (rolePatterns.totp.test(text)) return "totp-code";
  if (rolePatterns.userCode.test(text)) return "user-code";
  if (rolePatterns.verification.test(text)) return "verification-code";
  if (element.type === "email" || rolePatterns.email.test(text)) return "email";
  if (element.type === "date" || rolePatterns.birthDate.test(text))
    return "birth-date";
  if (rolePatterns.displayName.test(text)) return "display-name";
  if (rolePatterns.identifier.test(text)) return "username";
  return undefined;
}

/** Roles whose value arrives out of band rather than from the caller's hand. */
const outOfBandRoles: readonly CeremonyRole[] = [
  "verification-code",
  "totp-code",
  "user-code",
];

const secretRolesForPlan: readonly CeremonyRole[] = [
  "password",
  "password-confirm",
  "verification-code",
  "totp-code",
];

/**
 * Links worth following: they lead to another way in. A link that *does*
 * something — sends mail, revokes, signs out — is never followed, because
 * discovery must not cause an effect.
 */
const followable =
  /sign\s?in|log\s?in|sign\s?up|regist|create an?\s|passkey|security key|another way|different|instead|forgot|reset|recover/i;
const destructive =
  /resend|send|delete|remove|revoke|cancel|sign\s?out|log\s?out|deactivate|close account|unsubscribe/i;

function isFollowable(element: SnapshotElement): boolean {
  if (element.kind !== "link") return false;
  const text = element.text ?? "";
  if (!text.trim() || destructive.test(text)) return false;
  return followable.test(text);
}

/** What kind of step this page is, from its shape alone. */
function classifyByShape(snapshot: PageSnapshot): PageClassification {
  const fields = snapshot.elements.filter(
    (element) => element.kind === "input" || element.kind === "select",
  );
  const heading = snapshot.headings[0] ?? snapshot.title;
  if (snapshot.challenge)
    return {
      kind: "human",
      label: heading || "Clear the security check",
      humanReason: "challenge",
    };
  if (snapshot.passkey && !fields.some((field) => field.type === "password"))
    return {
      kind: "human",
      label: heading || "Use the platform authenticator",
      humanReason: "passkey",
    };
  if (fields.length > 0)
    return { kind: "form", label: heading || "Complete the form" };
  const buttons = snapshot.elements.filter(
    (element) => element.kind === "button",
  );
  if (buttons.length > 1)
    return { kind: "decision", label: heading || "Approve or refuse" };
  return { kind: "navigate", label: heading || "Continue" };
}

/* -------------------------------------------------------------------------- */
/* Walking the provider                                                       */
/* -------------------------------------------------------------------------- */

/** A route is the link captions clicked from the entry page, in order. */
type Route = readonly string[];

type Observed = {
  id: string;
  route: Route;
  snapshot: PageSnapshot;
  classification: PageClassification;
  /** Pages this one redirected through to get here, outermost first. */
  redirectedFrom: readonly string[];
};

function identifierFor(path: string, taken: Set<string>): string {
  const tail =
    new URL(path).pathname
      .split("/")
      .filter(Boolean)
      .join("-")
      .replace(/[^a-zA-Z0-9_.:-]/g, "") || "entry";
  const base = /^[a-zA-Z]/.test(tail) ? tail : `page-${tail}`;
  let id = base.slice(0, 90);
  let n = 2;
  while (taken.has(id)) id = `${base.slice(0, 86)}-${n++}`;
  taken.add(id);
  return id;
}

const originOf = (url: string) => new URL(url).origin;

/* -------------------------------------------------------------------------- */
/* Discovery                                                                  */
/* -------------------------------------------------------------------------- */

export async function discoverCeremony(
  options: DiscoveryOptions,
): Promise<DiscoveryResult> {
  const {
    page,
    entryUrl,
    goal,
    allowedOrigins,
    classifier,
    maxPages = 12,
    maxDepth = 2,
  } = options;
  const allowed = new Set(allowedOrigins.map((origin) => originOf(origin)));
  const uncertain: string[] = [];
  const visited: string[] = [];
  const observations: Observed[] = [];
  const takenIds = new Set<string>();
  const seenPaths = new Set<string>();

  /** Replay a route from the entry page. Only links are ever clicked. */
  const walk = async (route: Route): Promise<PageSnapshot | undefined> => {
    await page.goto(entryUrl);
    await page.settle();
    for (const caption of route) {
      const snapshot = await page.snapshot();
      const target = snapshot.elements.find(
        (element) => element.kind === "link" && element.text === caption,
      );
      if (!target) return undefined;
      await page.click(target);
      await page.settle();
    }
    return page.snapshot();
  };

  const queue: Route[] = [[]];
  const extended = new Set<string>();
  while (queue.length > 0 && visited.length < maxPages) {
    const route = queue.shift()!;
    const snapshot = await walk(route);
    if (!snapshot) {
      uncertain.push(
        `A link named "${route.at(-1)}" was not on the page the second time, so that branch was not explored.`,
      );
      continue;
    }
    const landed = await page.url();
    if (!allowed.has(originOf(landed))) {
      uncertain.push(
        `Following "${route.at(-1)}" left the origins discovery was permitted to read, so where it leads is unknown.`,
      );
      continue;
    }
    // The entry page redirecting elsewhere is the provider saying something has
    // to happen first. That is a prerequisite, and it is observable for free.
    const redirectedFrom =
      route.length === 0 && originOf(landed) === originOf(entryUrl)
        ? redirectChain(entryUrl, snapshot.path)
        : [];

    if (seenPaths.has(snapshot.path)) continue;
    seenPaths.add(snapshot.path);
    visited.push(snapshot.path);

    const classification =
      (await classifier?.({ goal, snapshot }).catch(() => undefined)) ??
      classifyByShape(snapshot);
    observations.push({
      id: identifierFor(snapshot.path, takenIds),
      route,
      snapshot,
      classification,
      redirectedFrom,
    });

    if (route.length >= maxDepth) continue;
    for (const element of snapshot.elements) {
      if (!isFollowable(element) || !element.text) continue;
      const next = [...route, element.text];
      const key = next.join(" > ");
      if (extended.has(key)) continue;
      extended.add(key);
      queue.push(next);
    }
  }

  if (observations.length === 0)
    throw new Error("Discovery read no page it was permitted to read");

  return {
    ...buildPlan(observations, { ...options, goal }, uncertain),
    uncertain,
    visited,
  };
}

/** A redirect away from the requested path is recorded as one hop. */
function redirectChain(requested: string, landed: string): readonly string[] {
  const from = new URL(requested);
  const to = new URL(landed);
  return from.pathname === to.pathname ? [] : [from.pathname];
}

/* -------------------------------------------------------------------------- */
/* Turning observations into a plan                                           */
/* -------------------------------------------------------------------------- */

function buildPlan(
  observations: readonly Observed[],
  options: DiscoveryOptions,
  uncertain: string[],
): { plan: CeremonyPlan } {
  const steps: PlanStep[] = [];
  const data: Record<string, PlanDatum> = {};
  /** Step ids each observation contributes, in the order they must run. */
  const chainOf = new Map<string, string[]>();

  for (const observed of observations) {
    const { snapshot, classification } = observed;
    const uses: string[] = [];
    const chain: string[] = [];

    const roles = new Map<CeremonyRole, string>();
    for (const element of snapshot.elements) {
      const role = inferRole(element, snapshot.elements);
      if (!role || roles.has(role)) continue;
      const key = role.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
      roles.set(role, key);
      uses.push(key);
      data[key] ??= {
        role,
        secret: secretRolesForPlan.includes(role),
        source: { from: "caller" },
        always: false,
      };
    }

    // A field asking for a code the provider sent means a step happened that
    // discovery never triggered: something delivered it. Naming that step is
    // what makes the plan runnable, and it is inferred, not observed.
    for (const [role, key] of roles) {
      if (!outOfBandRoles.includes(role)) continue;
      const producerId = `${observed.id}-delivery`;
      if (!steps.some((step) => step.id === producerId)) {
        steps.push({
          id: producerId,
          kind: "out-of-band",
          label: `Read the ${role.replace(/-/g, " ")} the provider sent`,
          needs: [],
          uses: [],
          produces: [key],
        });
        uncertain.push(
          `The ${role.replace(/-/g, " ")} on ${new URL(snapshot.path).pathname} arrives out of band; discovery did not trigger a send, so how it is delivered is not confirmed.`,
        );
      }
      data[key] = {
        ...data[key]!,
        source: { from: "step", step: producerId },
      };
      chain.push(producerId);
    }

    const step: PlanStep = {
      id: observed.id,
      kind: classification.kind,
      label: classification.label.slice(0, 120),
      at: snapshot.path,
      needs: [...chain],
      uses,
      produces: [],
      ...(classification.humanReason
        ? { humanReason: classification.humanReason }
        : {}),
    };
    steps.push(step);
    chain.push(observed.id);
    chainOf.set(observed.id, chain);

    for (const hop of observed.redirectedFrom)
      uncertain.push(
        `${hop} redirected to ${new URL(snapshot.path).pathname}, so that page is reached only after this one.`,
      );
  }

  // Every observation reached by following links from the entry page is its own
  // way through. The entry page is on all of them.
  const entry = observations[0]!;
  const branches = observations.filter(
    (observed) => observed.route.length > 0 && observed.id !== entry.id,
  );
  const entryChain = chainOf.get(entry.id)!;
  const routes: { id: string; label: string; chain: string[] }[] = [];
  // Staying on the entry page is itself a way through when there is something
  // to do there. A page that only forwards you somewhere is not.
  if (entry.classification.kind !== "navigate")
    routes.push({
      id: "direct",
      label: entry.classification.label.slice(0, 120),
      chain: entryChain,
    });
  for (const observed of branches)
    routes.push({
      id: `via-${observed.id}`.slice(0, 96),
      label:
        `${entry.classification.label} → ${observed.route.join(" → ")}`.slice(
          0,
          120,
        ),
      chain: [...entryChain, ...chainOf.get(observed.id)!],
    });
  if (routes.length === 0)
    routes.push({
      id: "direct",
      label: entry.classification.label.slice(0, 120),
      chain: entryChain,
    });
  routes.splice(PLAN_LIMITS.paths);

  const used = new Set(routes.flatMap((route) => route.chain));
  const keptSteps = steps.filter((step) => used.has(step.id));
  const keptData = Object.fromEntries(
    Object.entries(data).filter(([key]) =>
      keptSteps.some((step) => step.uses.includes(key)),
    ),
  );
  // A step may only require what every route that runs it also runs first.
  const byId = new Map(keptSteps.map((step) => [step.id, step]));
  for (const step of keptSteps)
    step.needs = step.needs.filter((need) =>
      routes
        .filter((route) => route.chain.includes(step.id))
        .every(
          (route) =>
            route.chain.indexOf(need) !== -1 &&
            route.chain.indexOf(need) < route.chain.indexOf(step.id),
        ),
    );

  const paths: PlanPath[] = routes.map((route) => {
    const chain = route.chain.filter((id) => byId.has(id));
    return {
      id: route.id,
      label: route.label,
      steps: chain,
      handoffs: chain.filter((id) => byId.get(id)?.kind === "human").length,
      when: [],
    };
  });

  for (const [key, datum] of Object.entries(keptData))
    keptData[key] = {
      ...datum,
      always: paths.every((path) =>
        path.steps.some((id) => byId.get(id)?.uses.includes(key)),
      ),
    };

  const plan = ceremonyPlanSchema.parse({
    schemaVersion: 1,
    id: options.id ?? "discovered",
    title: options.title ?? `Discovered ${options.goal} ceremony`,
    goal: options.goal,
    origin: originOf(options.entryUrl),
    data: keptData,
    steps: keptSteps,
    paths,
  } satisfies CeremonyPlan);
  return { plan };
}

import {
  createServer,
  type IncomingMessage,
  type Server,
  type ServerResponse,
} from "node:http";
import { createHash, randomBytes, randomInt } from "node:crypto";
import { SignJWT, jwtVerify } from "jose";
import type { AddressInfo } from "node:net";
import { createMarkup, type Markup } from "./markup.js";
import {
  verifyRequestSignature,
  type SignatureVerdict,
} from "../web-bot-auth.js";

/**
 * A self-hosted identity provider double.
 *
 * It is not a stub that returns canned strings: it serves real HTML over real
 * HTTP, keeps server-side sessions in cookies, enforces password, terms,
 * confirmation and second-factor rules, and implements authorization-code with
 * PKCE S256, a token endpoint, userinfo and OIDC discovery. Registration
 * delivers a real confirmation message to an outbox that the mailbox port reads.
 *
 * Because every page is regenerated per instance from a seed, the double is a
 * contract fixture rather than a golden page: passing it means the driver
 * understood the page, not that it memorised this provider.
 */

export type SeedAccount = {
  email: string;
  username: string;
  password: string;
  verified?: boolean;
};

export type ProviderBehavior = {
  seed?: number;
  accounts?: readonly SeedAccount[];
  /** Registration requires accepting terms before the account is created. */
  requireTerms?: boolean;
  /** Sign-in is followed by a one-time code page. */
  requireMfa?: boolean;
  /** How a new account is confirmed. */
  verification?: "code" | "link" | "none";
  /** Serve a human challenge instead of the named page. */
  challengeAt?: "sign-in" | "sign-up" | "consent";
  /** The consent page refuses and redirects with `error=access_denied`. */
  denyConsent?: boolean;
  /** Sign-in fails with a provider fault the first `n` times. */
  faultySignIns?: number;
  /** Sign-in posts to this absolute URL instead of its own origin. */
  hijackSignInTo?: string;
  /** Sign-in always redisplays itself without accepting or explaining. */
  neverAccept?: boolean;
  /** The sign-in button sits outside any form, so pressing it does nothing. */
  inertSignIn?: boolean;
  /**
   * A person can clear the challenge in the same browser. When false the widget
   * never passes, which is what an unsolvable wall looks like.
   */
  challengeClearable?: boolean;
  /** Sign-in is a passkey prompt with no password to fill. */
  passkeyOnly?: boolean;
  /** Sign-in hints at conditional passkey UI but still accepts a password. */
  conditionalPasskey?: boolean;
  /** The protected resource answers 401 with a Basic challenge and no page. */
  basicRealm?: string;
  /** Issue an ID token bound to the request nonce at the token endpoint. */
  openidConnect?: boolean;
  /** Accept RFC 7591 dynamic client registration before authorization. */
  dynamicRegistration?: boolean;
  /**
   * Honour `requested_actor` and `actor_token` as
   * draft-oauth-ai-agents-on-behalf-of-user-02 describes them: the consent
   * screen names the agent as well as the client, the token request must
   * authenticate that agent, and the issued access token carries `act`.
   */
  delegation?: boolean;
  /**
   * Actor identifiers this authorization server understands. The draft
   * requires the identifier be understood, so an unlisted one is refused
   * rather than silently accepted.
   */
  knownActors?: readonly string[];
  /**
   * Gate every page behind a Web Bot Auth signature
   * (draft-meunier-webbotauth-httpsig-protocol-02). A request that does not
   * carry a verifiable one is answered 403 with a human-verification
   * interstitial, which is the fork a real deployment presents: a recognised
   * agent passes straight through, an unrecognised one meets a person's work.
   */
  requireSignature?: boolean;
  clientId?: string;
  redirectUri?: string;
};

export type MailMessage = {
  to: string;
  subject: string;
  code: string;
  link: string;
  at: number;
};

export type Account = SeedAccount & { verified: boolean; totp: string };

export type ProviderDouble = {
  origin: string;
  markup: Markup;
  signupPath: string;
  behavior: ProviderBehavior;
  clientId: string;
  redirectUri: string;
  /** Start an authorization-code ceremony; returns the PKCE verifier too. */
  authorization(options?: {
    state?: string;
    scope?: string;
    clientId?: string;
    resource?: string;
    /** Agent to request delegated access for (`requested_actor`). */
    actor?: string;
  }): {
    url: string;
    verifier: string;
    state: string;
    nonce: string;
    clientId: string;
  };
  deviceUrl(userCode: string): string;
  issueDeviceCode(): string;
  account(email: string): Account | undefined;
  accounts(): readonly Account[];
  mailbox: {
    messages(): readonly MailMessage[];
    waitFor(to: string, timeoutMs?: number): Promise<MailMessage | undefined>;
  };
  /** Redeem an authorization code exactly as a relying party would. */
  exchange(
    code: string,
    verifier: string,
    options?: { actorToken?: string },
  ): Promise<{ status: number; body: Record<string, unknown> }>;
  /**
   * Mint a token authenticating an agent, as the agent's own issuer would.
   * Pass `issuer: "wrong"` to get one this authorization server will refuse.
   */
  actorToken(
    actor: string,
    options?: { issuer?: "agent" | "wrong" },
  ): Promise<string>;
  /** Read an issued access token the way a resource server would. */
  readAccessToken(
    token: string,
  ): Promise<{ sub: string; act?: { sub: string } } | undefined>;
  /** Provider-side proof that a session exists for this account. */
  verifyAccess(email: string): Promise<boolean>;
  /** Access tokens the provider displayed. Never something an agent may hold. */
  issuedTokens(): readonly string[];
  /** Applications a person installed, and accounts a federation accepted. */
  installed(): readonly string[];
  federated(): readonly string[];
  /** Accounts that completed an HTTP Basic exchange against the resource. */
  authenticatedBasic(): readonly string[];
  /** Every signature verdict the gate reached, oldest first. */
  signatureVerdicts(): readonly SignatureVerdict[];
  /** Validate an ID token the way a relying party would. */
  verifyIdToken(
    token: string,
  ): Promise<{ sub: string; nonce: string } | undefined>;
  close(): Promise<void>;
};

type PendingRegistration = {
  email: string;
  username: string;
  password: string;
  code: string;
  token: string;
};

type AuthorizationRequest = {
  clientId: string;
  redirectUri: string;
  challenge: string;
  state: string;
  scope: string;
  nonce: string;
  resource: string;
  /** The agent the user is being asked to delegate to, or "". */
  actor: string;
};

function cookies(request: IncomingMessage): Record<string, string> {
  const header = request.headers.cookie ?? "";
  return Object.fromEntries(
    header
      .split(";")
      .map((part) => part.trim().split("="))
      .filter((pair): pair is [string, string] => pair.length === 2),
  );
}

async function readBody(request: IncomingMessage): Promise<URLSearchParams> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) chunks.push(chunk as Buffer);
  return new URLSearchParams(Buffer.concat(chunks).toString("utf8"));
}

const digits = (length: number) =>
  Array.from({ length }, () => randomInt(0, 10)).join("");

export async function startAuthProvider(
  behavior: ProviderBehavior = {},
): Promise<ProviderDouble> {
  const markup = createMarkup(behavior.seed ?? 1);
  const clientId = behavior.clientId ?? "ceremony-test-client";
  const verification = behavior.verification ?? "code";
  const accounts = new Map<string, Account>();
  for (const seeded of behavior.accounts ?? [])
    accounts.set(seeded.email.toLowerCase(), {
      ...seeded,
      verified: seeded.verified ?? true,
      totp: digits(6),
    });
  const sessions = new Map<string, { email: string; factors: number }>();
  const pending = new Map<string, PendingRegistration>();
  const requests = new Map<string, AuthorizationRequest>();
  const grants = new Map<
    string,
    {
      email: string;
      verifier: string;
      redirectUri: string;
      nonce: string;
      resource: string;
      clientId: string;
      actor: string;
    }
  >();
  const devices = new Map<string, { approved: boolean; email?: string }>();
  /** Challenge tokens issued, and the browsers that have cleared one. */
  const challenges = new Set<string>();
  const cleared = new Set<string>();
  const installations = new Set<string>();
  const assertions = new Set<string>();
  const basicAccounts = new Set<string>();
  const idTokenKey = randomBytes(32);
  const verdicts: SignatureVerdict[] = [];
  const actorKey = randomBytes(32);
  const knownActors = new Set(behavior.knownActors ?? []);
  let closed = false;
  const clients = new Map<string, string>();
  const tokens = new Map<string, string>();
  const outbox: MailMessage[] = [];
  let faults = behavior.faultySignIns ?? 0;

  const server: Server = createServer((request, response) => {
    handle(request, response).catch(() => {
      response.writeHead(500, { "content-type": "text/html" });
      response.end(markup.page("Error", "<h1>Provider failure</h1>"));
    });
  });
  await new Promise<void>((resolve) =>
    server.listen(0, "127.0.0.1", () => resolve()),
  );
  const { port } = server.address() as AddressInfo;
  const origin = `http://127.0.0.1:${port}`;
  const redirectUri = behavior.redirectUri ?? `${origin}/callback`;

  const sessionOf = (request: IncomingMessage) => {
    const id = cookies(request)["sid"];
    return id ? sessions.get(id) : undefined;
  };
  /**
   * The agent's own issuer, kept separate from the authorization server so an
   * actor token is a real second credential rather than a restatement of the
   * first. Returns the agent it authenticates, or nothing.
   */
  const actorIssuer = `${origin}/agent-issuer`;
  const actorSubject = async (token: string): Promise<string | undefined> => {
    if (!token) return undefined;
    try {
      const { payload } = await jwtVerify(token, actorKey, {
        issuer: actorIssuer,
        audience: origin,
      });
      const subject = String(payload.sub ?? "");
      return subject || undefined;
    } catch {
      return undefined;
    }
  };

  const deliver = (to: string, code: string, token: string) => {
    outbox.push({
      to,
      subject: "Confirm your account",
      code,
      link: `${origin}/confirm/${token}`,
      at: Date.now(),
    });
  };

  async function handle(
    request: IncomingMessage,
    response: ServerResponse,
  ): Promise<void> {
    const url = new URL(request.url ?? "/", origin);
    const method = request.method ?? "GET";
    const body =
      method === "POST" ? await readBody(request) : new URLSearchParams();
    // A browser identity exists before any session does, so state such as a
    // cleared challenge can belong to the browser a person actually used.
    const existingBrowser = cookies(request)["bid"];
    const browserId = existingBrowser ?? randomBytes(12).toString("hex");
    const browser = () => browserId;
    const withCookies = (headers: Record<string, string>) => {
      const own = headers["set-cookie"];
      const extra = existingBrowser
        ? []
        : [`bid=${browserId}; Path=/; HttpOnly`];
      const all = [...(own ? [own] : []), ...extra];
      const rest = { ...headers };
      delete rest["set-cookie"];
      return all.length ? { ...rest, "set-cookie": all } : rest;
    };
    const send = (
      status: number,
      html: string,
      headers: Record<string, string> = {},
    ) => {
      response.writeHead(status, {
        "content-type": "text/html; charset=utf-8",
        ...withCookies(headers),
      });
      response.end(html);
    };
    const json = (
      status: number,
      value: unknown,
      headers: Record<string, string> = {},
    ) => {
      response.writeHead(status, {
        "content-type": "application/json",
        ...withCookies(headers),
      });
      response.end(JSON.stringify(value));
    };
    const redirect = (
      location: string,
      headers: Record<string, string> = {},
    ) => {
      response.writeHead(302, { location, ...withCookies(headers) });
      response.end();
    };
    const openSession = (email: string, factors: number) => {
      const id = randomBytes(16).toString("hex");
      sessions.set(id, { email, factors });
      return `sid=${id}; Path=/; HttpOnly`;
    };

    const challengePage = (status = 200) => {
      // The widget is the real obstacle; the form beside it is what a person
      // submits once they have satisfied it in their own browser.
      const token = randomBytes(8).toString("hex");
      if (behavior.challengeClearable) challenges.add(token);
      return send(
        status,
        markup.page(
          "Security check",
          `<h1>Confirm you are human</h1>
           <div data-captcha="required">Complete the challenge to continue.</div>
           ${
             behavior.challengeClearable
               ? `<form method="post" action="/challenge?to=${encodeURIComponent(url.pathname + url.search)}">
                    <input type="hidden" name="solved" value="${token}">
                    <button type="submit">I am not a robot</button>
                  </form>`
               : "<p>This step cannot be completed automatically.</p>"
           }`,
        ),
      );
    };

    const blocked = (at: ProviderBehavior["challengeAt"]) =>
      behavior.challengeAt === at && !cleared.has(browser());

    /**
     * The Web Bot Auth gate. A request carrying a signature this origin can
     * verify goes straight to the page it asked for; anything else gets 403
     * and the same interstitial a person would have to clear. The draft's
     * `Accept-Signature` says what would have been accepted, so an agent that
     * can sign learns to, rather than only learning it was refused.
     */
    const signatureGate = async (): Promise<boolean> => {
      if (!behavior.requireSignature) return true;
      const verdict = await verifyRequestSignature(
        request.headers as Record<string, string | string[] | undefined>,
        request.headers.host ?? "",
      );
      verdicts.push(verdict);
      if (verdict.ok) return true;
      // A cleared challenge stands in for the human-verified cookie a real
      // interstitial sets, so a person's work is not demanded on every page.
      if (cleared.has(browser())) return true;
      response.setHeader(
        "accept-signature",
        'sig=("@authority");keyid;created;expires;tag="web-bot-auth"',
      );
      challengePage(403);
      return false;
    };

    const signInPage = (next: string, error?: string) => {
      if (blocked("sign-in")) return challengePage();
      if (behavior.passkeyOnly)
        return send(
          200,
          markup.page(
            "Use your passkey",
            `<h1>Use your passkey to continue</h1>
             <div data-passkey="required">Your device will ask for the passkey.</div>
             <form method="post" action="/passkey?next=${encodeURIComponent(next)}">
               <button type="submit">Continue with passkey</button>
             </form>`,
          ),
        );
      const action =
        behavior.hijackSignInTo ??
        `${url.pathname}?next=${encodeURIComponent(next)}`;
      const fields = markup.arrange("sign-in", [
        markup.field(
          markup.labels.identifier,
          markup.names.identifier,
          "text",
          behavior.conditionalPasskey
            ? 'required autocomplete="username webauthn"'
            : "required",
        ),
        markup.field(
          markup.labels.password,
          markup.names.password,
          "password",
          "required",
        ),
      ]);
      if (behavior.inertSignIn)
        return send(
          200,
          markup.page(
            "Sign in",
            `${markup.alert(error)}
             <h1>${markup.headings.signIn}</h1>
             ${fields.join("\n")}
             <button type="button">${markup.captions.signIn}</button>`,
          ),
        );
      send(
        200,
        markup.page(
          "Sign in",
          `${markup.alert(error)}
           <h1>${markup.headings.signIn}</h1>
           <form method="post" action="${action}">
             ${fields.join("\n")}
             <button type="submit">${markup.captions.signIn}</button>
           </form>
           <p><a href="${markup.signupPath}?next=${encodeURIComponent(next)}">${markup.captions.signUpLink}</a></p>`,
        ),
      );
    };

    const signUpPage = (next: string, error?: string) => {
      if (blocked("sign-up")) return challengePage();
      const fields = markup.arrange("sign-up", [
        markup.field(
          markup.labels.email,
          markup.names.email,
          markup.emailInputType,
          "required",
        ),
        markup.field(
          markup.labels.password,
          markup.names.password,
          "password",
          "required",
        ),
        markup.field(
          markup.labels.confirm,
          markup.names.confirm,
          "password",
          "required",
        ),
        ...(markup.includeDisplayName
          ? [
              markup.field(
                markup.labels.displayName,
                markup.names.displayName,
                "text",
              ),
            ]
          : []),
        ...(markup.includeBirthDate
          ? [
              markup.field(
                markup.labels.birthDate,
                markup.names.birthDate,
                "date",
              ),
            ]
          : []),
        ...(behavior.requireTerms
          ? [markup.checkbox(markup.labels.terms, markup.names.terms)]
          : []),
      ]);
      send(
        200,
        markup.page(
          "Create account",
          `${markup.alert(error)}
           <h1>${markup.headings.signUp}</h1>
           <form method="post" action="${markup.signupPath}?next=${encodeURIComponent(next)}">
             ${fields.join("\n")}
             <button type="submit">${markup.captions.signUp}</button>
           </form>`,
        ),
      );
    };

    const confirmPage = (token: string, next: string, error?: string) =>
      send(
        200,
        markup.page(
          "Confirm your account",
          `${markup.alert(error)}
           <h1>${markup.messages.checkInbox}</h1>
           <form method="post" action="/confirm?p=${token}&next=${encodeURIComponent(next)}">
             ${markup.field(markup.labels.verification, markup.names.code, "text", 'required inputmode="numeric"')}
             <button type="submit">${markup.captions.submitCode}</button>
           </form>
           <form method="post" action="/resend?p=${token}">
             <button type="submit">${markup.captions.resend}</button>
           </form>`,
        ),
      );

    const mfaPage = (id: string, target: string, error?: string) =>
      send(
        200,
        markup.page(
          "Two-factor",
          `${markup.alert(error)}
           <h1>Enter your ${markup.escape(markup.labels.totp)}</h1>
           <form method="post" action="/mfa?next=${encodeURIComponent(target)}">
             ${markup.field(markup.labels.totp, markup.names.code, "text", "required")}
             <button type="submit">${markup.captions.submitCode}</button>
           </form>`,
        ),
        { "set-cookie": `sid=${id}; Path=/; HttpOnly` },
      );

    const dashboard = (email: string) =>
      send(
        200,
        markup.page(
          "Account",
          `<h1>You are signed in</h1>
           <p data-account="${markup.escape(email)}">Signed in as ${markup.escape(email)}.</p>
           <form method="post" action="/signout"><button type="submit">Sign out</button></form>`,
        ),
      );

    const next = url.searchParams.get("next") ?? "/";

    // The challenge endpoint has to stay reachable, or a person sent to clear
    // the interstitial would be refused on the way to clearing it.
    if (url.pathname !== "/challenge" && !(await signatureGate())) return;

    if (url.pathname === "/.well-known/openid-configuration")
      return json(200, {
        issuer: origin,
        authorization_endpoint: `${origin}/authorize`,
        token_endpoint: `${origin}/token`,
        userinfo_endpoint: `${origin}/userinfo`,
        code_challenge_methods_supported: ["S256"],
        ...(behavior.dynamicRegistration
          ? { registration_endpoint: `${origin}/oauth/register` }
          : {}),
        response_types_supported: ["code"],
        grant_types_supported: ["authorization_code"],
      });

    if (url.pathname === "/") {
      const session = sessionOf(request);
      if (!session) return redirect("/signin");
      if (behavior.requireMfa && session.factors < 2) return redirect("/mfa");
      return dashboard(session.email);
    }

    if (url.pathname === "/signin") {
      if (method === "GET") return signInPage(next);
      if (faults > 0) {
        faults--;
        return send(
          503,
          markup.page(
            "Unavailable",
            `${markup.alert("Sign-in is temporarily unavailable. Try again.")}
             <h1>Service unavailable</h1>
             <p><a href="${url.pathname}?next=${encodeURIComponent(next)}">Try again</a></p>`,
          ),
        );
      }
      if (behavior.neverAccept) return signInPage(next);
      const identifier = (body.get(markup.names.identifier) ?? "").trim();
      const password = body.get(markup.names.password) ?? "";
      const found = [...accounts.values()].find(
        (account) =>
          account.username.toLowerCase() === identifier.toLowerCase() ||
          account.email.toLowerCase() === identifier.toLowerCase(),
      );
      if (!found || found.password !== password)
        return signInPage(next, markup.messages.rejected);
      if (!found.verified) {
        const token = randomBytes(12).toString("hex");
        const code = digits(6);
        pending.set(token, {
          email: found.email,
          username: found.username,
          password: found.password,
          code,
          token,
        });
        deliver(found.email, code, token);
        return confirmPage(token, next, markup.messages.unverified);
      }
      const cookie = openSession(found.email, behavior.requireMfa ? 1 : 2);
      if (behavior.requireMfa) {
        const id = cookie.slice("sid=".length, cookie.indexOf(";"));
        return mfaPage(id, next);
      }
      return redirect(next, { "set-cookie": cookie });
    }

    if (url.pathname === "/mfa") {
      const session = sessionOf(request);
      if (!session) return redirect("/signin");
      if (method === "GET") {
        const id = cookies(request)["sid"] ?? "";
        return mfaPage(id, next);
      }
      const account = accounts.get(session.email.toLowerCase());
      if (!account || body.get(markup.names.code) !== account.totp) {
        const id = cookies(request)["sid"] ?? "";
        return mfaPage(id, next, markup.messages.badCode);
      }
      session.factors = 2;
      return redirect(next);
    }

    if (url.pathname === markup.signupPath) {
      if (method === "GET") return signUpPage(next);
      const email = (body.get(markup.names.email) ?? "").trim().toLowerCase();
      const password = body.get(markup.names.password) ?? "";
      const confirm = body.get(markup.names.confirm) ?? "";
      if (behavior.requireTerms && body.get(markup.names.terms) !== "yes")
        return signUpPage(next, markup.messages.termsRequired);
      if (!email.includes("@") || password.length < 8)
        return signUpPage(
          next,
          "Enter an email address and a password of at least 8 characters.",
        );
      if (password !== confirm)
        return signUpPage(next, markup.messages.mismatch);
      if (accounts.has(email))
        return signUpPage(next, markup.messages.emailInUse);
      const username = email.split("@")[0] ?? email;
      if (verification === "none") {
        accounts.set(email, {
          email,
          username,
          password,
          verified: true,
          totp: digits(6),
        });
        return redirect(next, { "set-cookie": openSession(email, 2) });
      }
      const token = randomBytes(12).toString("hex");
      const code = digits(6);
      pending.set(token, { email, username, password, code, token });
      deliver(email, code, token);
      return confirmPage(token, next);
    }

    if (url.pathname === "/resend" && method === "POST") {
      const record = pending.get(url.searchParams.get("p") ?? "");
      if (!record) return redirect("/signin");
      deliver(record.email, record.code, record.token);
      return confirmPage(record.token, next, undefined);
    }

    if (url.pathname.startsWith("/confirm")) {
      const linkToken = url.pathname.slice("/confirm/".length);
      if (url.pathname !== "/confirm" && method === "GET") {
        const record = pending.get(linkToken);
        if (!record) return signInPage(next, markup.messages.rejected);
        pending.delete(linkToken);
        accounts.set(record.email, {
          email: record.email,
          username: record.username,
          password: record.password,
          verified: true,
          totp: digits(6),
        });
        return redirect(next, { "set-cookie": openSession(record.email, 2) });
      }
      const token = url.searchParams.get("p") ?? "";
      const record = pending.get(token);
      if (!record) return signInPage(next, markup.messages.rejected);
      if (method === "GET") return confirmPage(token, next);
      if (body.get(markup.names.code) !== record.code)
        return confirmPage(token, next, markup.messages.badCode);
      pending.delete(token);
      accounts.set(record.email, {
        email: record.email,
        username: record.username,
        password: record.password,
        verified: true,
        totp: digits(6),
      });
      return redirect(next, { "set-cookie": openSession(record.email, 2) });
    }

    if (url.pathname === "/authorize") {
      const session = sessionOf(request);
      if (!session || (behavior.requireMfa && session.factors < 2))
        return redirect(
          `/signin?next=${encodeURIComponent(url.pathname + url.search)}`,
        );
      if (blocked("consent")) return challengePage();
      const actor = url.searchParams.get("requested_actor") ?? "";
      // The draft requires the identifier be one the server understands. An
      // unrecognised agent is refused at the redirect, so the client learns the
      // delegation was rejected rather than silently receiving a plain grant.
      if (behavior.delegation && actor && !knownActors.has(actor)) {
        const refusal = new URL(url.searchParams.get("redirect_uri") ?? origin);
        refusal.searchParams.set("error", "invalid_request");
        const sent = url.searchParams.get("state");
        if (sent) refusal.searchParams.set("state", sent);
        return redirect(refusal.href);
      }
      const requestId = randomBytes(8).toString("hex");
      requests.set(requestId, {
        clientId: url.searchParams.get("client_id") ?? "",
        redirectUri: url.searchParams.get("redirect_uri") ?? "",
        challenge: url.searchParams.get("code_challenge") ?? "",
        state: url.searchParams.get("state") ?? "",
        scope: url.searchParams.get("scope") ?? "",
        nonce: url.searchParams.get("nonce") ?? "",
        resource: url.searchParams.get("resource") ?? "",
        actor: behavior.delegation ? actor : "",
      });
      // Delegation is a different question from access, so the page asks it
      // out loud: this names the agent, not just the client asking.
      const delegation =
        behavior.delegation && actor
          ? `<p>${markup.escape(actor)} will act on your behalf.</p>`
          : "";
      return send(
        200,
        markup.page(
          "Authorize",
          `<h1>${markup.headings.consent}</h1>
           <p>${markup.escape(clientId)} is requesting ${markup.escape(url.searchParams.get("scope") ?? "access")}.</p>
           ${delegation}
           <form method="post" action="/consent">
             <input type="hidden" name="r" value="${requestId}">
             <button type="submit" name="decision" value="allow">${markup.captions.approve}</button>
             <button type="submit" name="decision" value="deny">${markup.captions.deny}</button>
           </form>`,
        ),
      );
    }

    if (url.pathname === "/consent" && method === "POST") {
      const session = sessionOf(request);
      const pendingRequest = requests.get(body.get("r") ?? "");
      if (!session || !pendingRequest) return redirect("/signin");
      const target = new URL(pendingRequest.redirectUri);
      if (behavior.denyConsent || body.get("decision") === "deny") {
        target.searchParams.set("error", "access_denied");
        if (pendingRequest.state)
          target.searchParams.set("state", pendingRequest.state);
        return redirect(target.href);
      }
      const code = randomBytes(24).toString("hex");
      grants.set(code, {
        email: session.email,
        verifier: pendingRequest.challenge,
        redirectUri: pendingRequest.redirectUri,
        nonce: pendingRequest.nonce,
        resource: pendingRequest.resource,
        clientId: pendingRequest.clientId,
        actor: pendingRequest.actor,
      });
      target.searchParams.set("code", code);
      if (pendingRequest.state)
        target.searchParams.set("state", pendingRequest.state);
      return redirect(target.href);
    }

    if (url.pathname === "/token" && method === "POST") {
      const code = body.get("code") ?? "";
      const grant = grants.get(code);
      const verifier = body.get("code_verifier") ?? "";
      const derived = createHash("sha256").update(verifier).digest("base64url");
      if (
        !grant ||
        grant.verifier !== derived ||
        body.get("redirect_uri") !== grant.redirectUri
      )
        return json(400, { error: "invalid_grant" });
      // Delegation is only real if the agent authenticates too: a code alone
      // must not buy a token that claims someone acts for the user.
      let acting: string | undefined;
      if (grant.actor) {
        const presented = body.get("actor_token") ?? "";
        const subject = await actorSubject(presented);
        if (!subject || subject !== grant.actor)
          return json(400, { error: "invalid_grant" });
        acting = subject;
      }
      grants.delete(code);
      const issued: Record<string, unknown> = {
        access_token: acting
          ? await new SignJWT({ act: { sub: acting } })
              .setProtectedHeader({ alg: "HS256" })
              .setIssuer(origin)
              .setAudience(grant.clientId || clientId)
              .setSubject(grant.email)
              .setIssuedAt()
              .setExpirationTime("5m")
              .sign(idTokenKey)
          : `at_${randomBytes(16).toString("hex")}`,
        token_type: "Bearer",
        expires_in: 3600,
        scope: "openid",
        sub: grant.email,
        client_id: grant.clientId,
        // MCP binds a token to the resource the client asked for; echoing it
        // is what lets a consumer check it got the audience it requested.
        ...(grant.resource ? { aud: grant.resource } : {}),
      };
      if (behavior.openidConnect)
        // A real signed assertion, so a consumer's nonce and issuer checks are
        // exercised rather than assumed.
        issued["id_token"] = await new SignJWT({
          nonce: grant.nonce,
          email: grant.email,
        })
          .setProtectedHeader({ alg: "HS256" })
          .setIssuer(origin)
          .setAudience(grant.verifier ? clientId : clientId)
          .setSubject(grant.email)
          .setIssuedAt()
          .setExpirationTime("5m")
          .sign(idTokenKey);
      return json(200, issued);
    }

    if (url.pathname === "/userinfo") {
      const session = sessionOf(request);
      if (!session) return json(401, { error: "invalid_token" });
      return json(200, { sub: session.email, email: session.email });
    }

    if (url.pathname === "/device") {
      const session = sessionOf(request);
      if (!session)
        return redirect(`/signin?next=${encodeURIComponent("/device")}`);
      if (method === "GET")
        return send(
          200,
          markup.page(
            "Connect a device",
            `<h1>Enter the code shown on your device</h1>
             <form method="post" action="/device">
               ${markup.field(markup.labels.userCode, markup.names.userCode, "text", "required")}
               <button type="submit">${markup.captions.approve}</button>
             </form>`,
          ),
        );
      const entered = (body.get(markup.names.userCode) ?? "")
        .trim()
        .toUpperCase();
      const device = devices.get(entered);
      if (!device)
        return send(
          200,
          markup.page(
            "Connect a device",
            `${markup.alert(markup.messages.badCode)}
             <h1>Enter the code shown on your device</h1>
             <form method="post" action="/device">
               ${markup.field(markup.labels.userCode, markup.names.userCode, "text", "required")}
               <button type="submit">${markup.captions.approve}</button>
             </form>`,
          ),
        );
      device.approved = true;
      device.email = session.email;
      return send(
        200,
        markup.page(
          "Device connected",
          `<h1>You are signed in</h1><p data-account="${markup.escape(session.email)}">The device is now approved.</p>`,
        ),
      );
    }

    // A person clears the widget in the same browser they were handed. The
    // clearance belongs to that browser, so the agent resuming there sees it.
    // Only a person can satisfy the authenticator; the provider then opens the
    // session, exactly as it would after a real assertion.
    if (url.pathname === "/passkey" && method === "POST") {
      const account = [...accounts.values()][0];
      if (!account) return redirect("/signin");
      return redirect(url.searchParams.get("next") ?? "/", {
        "set-cookie": openSession(account.email, 2),
      });
    }

    if (url.pathname === "/challenge" && method === "POST") {
      const solved = body.get("solved") ?? "";
      if (!challenges.has(solved)) return redirect("/signin");
      challenges.delete(solved);
      cleared.add(browser());
      return redirect(url.searchParams.get("to") ?? "/");
    }

    // Personal access tokens: the value is shown on the page, never in a field.
    // An agent can reach this page; only a person may carry the value onward.
    if (url.pathname === "/tokens") {
      const session = sessionOf(request);
      if (!session)
        return redirect(`/signin?next=${encodeURIComponent("/tokens")}`);
      if (method === "GET")
        return send(
          200,
          markup.page(
            "Access tokens",
            `<h1>Personal access tokens</h1>
             <form method="post" action="/tokens">
               ${markup.field("Token name", "token_name", "text", "required")}
               <button type="submit">Generate token</button>
             </form>`,
          ),
        );
      const issued = `pat_${randomBytes(20).toString("hex")}`;
      tokens.set(issued, session.email);
      return send(
        200,
        markup.page(
          "Access tokens",
          `<h1>Copy your new token</h1>
           <p>This value is shown once. Copy it into the application now.</p>
           <code data-token>${issued}</code>`,
        ),
      );
    }

    // HTTP Basic: the challenge is a header, so there is no page to fill.
    if (url.pathname === "/basic") {
      if (!behavior.basicRealm) return send(404, markup.page("Not found", ""));
      const header = request.headers.authorization ?? "";
      const [scheme, encoded] = header.split(" ");
      const [user, secret] = Buffer.from(encoded ?? "", "base64")
        .toString("utf8")
        .split(":");
      const account = [...accounts.values()].find(
        (candidate) =>
          candidate.username.toLowerCase() === (user ?? "").toLowerCase() ||
          candidate.email.toLowerCase() === (user ?? "").toLowerCase(),
      );
      if (
        scheme?.toLowerCase() !== "basic" ||
        !account ||
        account.password !== secret
      ) {
        response.writeHead(401, {
          "www-authenticate": `Basic realm="${behavior.basicRealm}", charset="UTF-8"`,
          "content-type": "text/html; charset=utf-8",
        });
        response.end(markup.page("Unauthorized", "<h1>401</h1>"));
        return;
      }
      basicAccounts.add(account.email.toLowerCase());
      return send(
        200,
        markup.page(
          "Protected",
          `<h1>You are signed in</h1><p data-account="${markup.escape(account.email)}">Basic access granted.</p>`,
        ),
      );
    }

    // A resource that explicitly needs no authentication at all.
    if (url.pathname === "/public")
      return send(
        200,
        markup.page(
          "Public resource",
          `<h1>You are signed in</h1><p>This resource is public; no account is required.</p>`,
        ),
      );

    // auth.md anonymous identity, claimed later with an emailed approval code.
    if (url.pathname === "/anonymous") {
      if (method === "GET")
        return send(
          200,
          markup.page(
            "Anonymous access",
            `<h1>Continue without an account</h1>
             <form method="post" action="/anonymous">
               <button type="submit">Continue anonymously</button>
             </form>`,
          ),
        );
      const handle = `anon-${randomBytes(6).toString("hex")}`;
      accounts.set(handle, {
        email: handle,
        username: handle,
        password: randomBytes(12).toString("hex"),
        verified: false,
        totp: digits(6),
      });
      return redirect("/claim", { "set-cookie": openSession(handle, 1) });
    }

    if (url.pathname === "/claim") {
      const session = sessionOf(request);
      if (!session) return redirect("/anonymous");
      if (method === "GET")
        return send(
          200,
          markup.page(
            "Claim this access",
            `<h1>Claim your anonymous access</h1>
             <form method="post" action="/claim">
               ${markup.field(markup.labels.email, markup.names.email, markup.emailInputType, "required")}
               <button type="submit">Send approval code</button>
             </form>`,
          ),
        );
      const address = (body.get(markup.names.email) ?? "").trim().toLowerCase();
      const existing = pending.get(session.email);
      if (!existing && address.includes("@")) {
        const code = digits(6);
        pending.set(session.email, {
          email: address,
          username: session.email,
          password: "",
          code,
          token: session.email,
        });
        deliver(address, code, session.email);
        return send(
          200,
          markup.page(
            "Claim this access",
            `<h1>${markup.messages.checkInbox}</h1>
             <form method="post" action="/claim">
               ${markup.field(markup.labels.verification, markup.names.code, "text", "required")}
               <button type="submit">${markup.captions.submitCode}</button>
             </form>`,
          ),
        );
      }
      if (!existing) return redirect("/claim");
      if (body.get(markup.names.code) !== existing.code)
        return send(
          200,
          markup.page(
            "Claim this access",
            `${markup.alert(markup.messages.badCode)}
             <h1>${markup.messages.checkInbox}</h1>
             <form method="post" action="/claim">
               ${markup.field(markup.labels.verification, markup.names.code, "text", "required")}
               <button type="submit">${markup.captions.submitCode}</button>
             </form>`,
          ),
        );
      pending.delete(session.email);
      const claimed = accounts.get(session.email);
      if (claimed) claimed.verified = true;
      session.factors = 2;
      return send(
        200,
        markup.page(
          "Claimed",
          `<h1>You are signed in</h1><p data-account="${markup.escape(existing.email)}">This access is now claimed.</p>`,
        ),
      );
    }

    // GitHub App shape: a manifest is submitted, then the app is installed.
    if (url.pathname === "/apps/new") {
      const session = sessionOf(request);
      if (!session)
        return redirect(`/signin?next=${encodeURIComponent("/apps/new")}`);
      if (method === "GET")
        return send(
          200,
          markup.page(
            "Register an application",
            `<h1>Register a new application</h1>
             <form method="post" action="/apps/new">
               ${markup.field("Application name", "app_name", "text", "required")}
               <button type="submit">Create application</button>
             </form>`,
          ),
        );
      const app = randomBytes(6).toString("hex");
      clients.set(app, session.email);
      return redirect(`/apps/${app}/install`);
    }

    if (
      url.pathname.startsWith("/apps/") &&
      url.pathname.endsWith("/install")
    ) {
      const session = sessionOf(request);
      const app = url.pathname.slice("/apps/".length, -"/install".length);
      if (!session || !clients.has(app)) return redirect("/signin");
      if (method === "GET")
        return send(
          200,
          markup.page(
            "Install application",
            `<h1>Install this application</h1>
             <p>Choose where it may act on your behalf.</p>
             <form method="post" action="${url.pathname}">
               <button type="submit">${markup.captions.approve}</button>
             </form>`,
          ),
        );
      installations.add(app);
      return send(
        200,
        markup.page(
          "Installed",
          `<h1>You are signed in</h1><p data-account="${markup.escape(session.email)}">The application is installed.</p>`,
        ),
      );
    }

    // RFC 7591 dynamic client registration, as MCP authorization expects.
    if (url.pathname === "/oauth/register" && method === "POST") {
      if (!behavior.dynamicRegistration)
        return json(404, { error: "not_found" });
      const id = `client_${randomBytes(8).toString("hex")}`;
      clients.set(id, "dynamic");
      return json(201, { client_id: id, token_endpoint_auth_method: "none" });
    }

    if (url.pathname === "/.well-known/oauth-protected-resource")
      return json(200, {
        resource: `${origin}/resource`,
        authorization_servers: [origin],
      });

    // SAML SP-initiated flow: authenticate, then hand back a signed assertion
    // through the POST binding, with the no-script submit real IdPs include.
    if (url.pathname === "/saml/login") {
      const session = sessionOf(request);
      const relay = url.searchParams.get("RelayState") ?? "";
      if (!session)
        return redirect(
          `/signin?next=${encodeURIComponent(url.pathname + url.search)}`,
        );
      const assertion = Buffer.from(
        `<Assertion><Subject>${session.email}</Subject><Audience>${clientId}</Audience></Assertion>`,
      ).toString("base64");
      return send(
        200,
        markup.page(
          "Signing you in",
          `<h1>Completing sign-in</h1>
           <form method="post" action="/saml/acs">
             <input type="hidden" name="SAMLResponse" value="${assertion}">
             <input type="hidden" name="RelayState" value="${markup.escape(relay)}">
             <button type="submit">Continue</button>
           </form>`,
        ),
      );
    }

    if (url.pathname === "/saml/acs" && method === "POST") {
      const decoded = Buffer.from(
        body.get("SAMLResponse") ?? "",
        "base64",
      ).toString("utf8");
      const subject = /<Subject>([^<]+)<\/Subject>/.exec(decoded)?.[1] ?? "";
      if (!accounts.has(subject.toLowerCase()))
        return send(
          401,
          markup.page("Rejected", "<h1>Assertion rejected</h1>"),
        );
      assertions.add(subject.toLowerCase());
      return send(
        200,
        markup.page(
          "Federated",
          `<h1>You are signed in</h1><p data-account="${markup.escape(subject)}">The assertion was accepted.</p>`,
        ),
      );
    }

    if (url.pathname === "/signout" && method === "POST") {
      const id = cookies(request)["sid"];
      if (id) sessions.delete(id);
      return redirect("/signin");
    }

    return send(404, markup.page("Not found", "<h1>Not found</h1>"));
  }

  return {
    origin,
    markup,
    behavior,
    clientId,
    redirectUri,
    signupPath: markup.signupPath,
    authorization: (options = {}) => {
      const verifier = randomBytes(32).toString("base64url");
      const state = options.state ?? randomBytes(8).toString("hex");
      const nonce = randomBytes(8).toString("hex");
      const challenge = createHash("sha256")
        .update(verifier)
        .digest("base64url");
      const target = new URL(`${origin}/authorize`);
      const client = options.clientId ?? clientId;
      target.searchParams.set("client_id", client);
      if (options.resource)
        target.searchParams.set("resource", options.resource);
      target.searchParams.set("redirect_uri", redirectUri);
      target.searchParams.set("response_type", "code");
      target.searchParams.set("code_challenge", challenge);
      target.searchParams.set("code_challenge_method", "S256");
      target.searchParams.set("scope", options.scope ?? "openid profile");
      target.searchParams.set("state", state);
      target.searchParams.set("nonce", nonce);
      if (options.actor)
        target.searchParams.set("requested_actor", options.actor);
      return { url: target.href, verifier, state, nonce, clientId: client };
    },
    deviceUrl: (userCode) => `${origin}/device?user_code=${userCode}`,
    issueDeviceCode: () => {
      const code = randomBytes(3).toString("hex").toUpperCase();
      devices.set(code, { approved: false });
      return code;
    },
    account: (email) => accounts.get(email.toLowerCase()),
    accounts: () => [...accounts.values()],
    mailbox: {
      messages: () => [...outbox],
      waitFor: async (to, timeoutMs = 2_000) => {
        const deadline = Date.now() + timeoutMs;
        const address = to.toLowerCase();
        for (;;) {
          const found = [...outbox]
            .reverse()
            .find((message) => message.to.toLowerCase() === address);
          if (found) return found;
          if (Date.now() >= deadline) return undefined;
          await new Promise((resolve) => setTimeout(resolve, 10));
        }
      },
    },
    exchange: async (code, verifier, options = {}) => {
      const result = await fetch(`${origin}/token`, {
        method: "POST",
        headers: { "content-type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          grant_type: "authorization_code",
          code,
          code_verifier: verifier,
          redirect_uri: redirectUri,
          client_id: clientId,
          ...(options.actorToken ? { actor_token: options.actorToken } : {}),
        }),
      });
      return {
        status: result.status,
        body: (await result.json()) as Record<string, unknown>,
      };
    },
    actorToken: (actor, options = {}) =>
      new SignJWT({})
        .setProtectedHeader({ alg: "HS256" })
        .setIssuer(options.issuer === "wrong" ? origin : actorIssuer)
        .setAudience(origin)
        .setSubject(actor)
        .setIssuedAt()
        .setExpirationTime("5m")
        .sign(actorKey),
    readAccessToken: async (token) => {
      try {
        const { payload } = await jwtVerify(token, idTokenKey, {
          issuer: origin,
        });
        const act = payload["act"] as { sub?: string } | undefined;
        return {
          sub: String(payload.sub ?? ""),
          ...(act?.sub ? { act: { sub: act.sub } } : {}),
        };
      } catch {
        return undefined;
      }
    },
    issuedTokens: () => [...tokens.keys()],
    installed: () => [...installations],
    federated: () => [...assertions],
    authenticatedBasic: () => [...basicAccounts],
    signatureVerdicts: () => [...verdicts],
    verifyIdToken: async (token) => {
      try {
        const { payload } = await jwtVerify(token, idTokenKey, {
          issuer: origin,
          audience: clientId,
        });
        return {
          sub: String(payload.sub ?? ""),
          nonce: String(payload["nonce"] ?? ""),
        };
      } catch {
        return undefined;
      }
    },
    verifyAccess: async (email) =>
      [...sessions.values()].some(
        (session) =>
          session.email.toLowerCase() === email.toLowerCase() &&
          session.factors >= 2,
      ),
    close: async () => {
      if (closed) return;
      closed = true;
      // `close` alone waits on idle keep-alive sockets, which a fixture that
      // just served a ceremony always has; dropping them releases the port.
      server.closeAllConnections();
      await new Promise<void>((resolve, reject) =>
        server.close((error) => (error ? reject(error) : resolve())),
      );
    },
  };
}

/**
 * A second origin that is not part of any ceremony's allowlist. It imitates the
 * provider's sign-in page so a driver that follows a redirect off the permitted
 * origin would type a password into it. Nothing here ever receives one: the
 * contract asserts the attempt stops first.
 */
export async function startUntrustedOrigin(): Promise<{
  origin: string;
  submissions(): readonly Record<string, string>[];
  close(): Promise<void>;
}> {
  const submissions: Record<string, string>[] = [];
  const server = createServer((request, response) => {
    void (async () => {
      if (request.method === "POST") {
        const body = await readBody(request);
        submissions.push(Object.fromEntries(body.entries()));
      }
      response.writeHead(200, { "content-type": "text/html; charset=utf-8" });
      response.end(
        `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Sign in</title></head><body>
         <h1>Sign in to continue</h1>
         <form method="post" action="/">
           <p><label for="u">Username</label><input id="u" name="username" type="text" required></p>
           <p><label for="p">Password</label><input id="p" name="password" type="password" required></p>
           <button type="submit">Sign in</button>
         </form></body></html>`,
      );
    })();
  });
  await new Promise<void>((resolve) =>
    server.listen(0, "127.0.0.1", () => resolve()),
  );
  const { port } = server.address() as AddressInfo;
  let shut = false;
  return {
    origin: `http://127.0.0.1:${port}`,
    submissions: () => [...submissions],
    close: async () => {
      if (shut) return;
      shut = true;
      server.closeAllConnections();
      await new Promise<void>((resolve, reject) =>
        server.close((error) => (error ? reject(error) : resolve())),
      );
    },
  };
}

import { parseHTML } from "linkedom";
import {
  snapshotDocument,
  snapshotSelectors,
  type PageSnapshot,
  type SnapshotElement,
} from "../../src/core/browser-contracts.js";
import type { CeremonyPage } from "../../src/server/browser-driver.js";

/**
 * A `CeremonyPage` backed by real HTTP requests and a real parsed document.
 *
 * Navigation, cookies, redirects and form serialization behave as a browser's
 * do; the page is built by the same `snapshotDocument` the Playwright adapter
 * ships into a live browser, so a snapshot here is the snapshot there. What it
 * does not do is run scripts — which is why the same scenarios are also run
 * through a real Chromium in the browser suite, and why neither result is
 * reported as covering the other.
 */

type Jar = Map<string, string>;

function storeCookies(jar: Jar, response: Response): void {
  const header = response.headers.getSetCookie?.() ?? [];
  for (const cookie of header) {
    const [pair] = cookie.split(";");
    const separator = pair?.indexOf("=") ?? -1;
    if (!pair || separator <= 0) continue;
    jar.set(pair.slice(0, separator), pair.slice(separator + 1));
  }
}

function cookieHeader(jar: Jar): string {
  return [...jar.entries()]
    .map(([name, value]) => `${name}=${value}`)
    .join("; ");
}

/** Controls a browser would submit, matching HTML form serialization rules. */
function serialize(form: Element, submitter?: Element): URLSearchParams {
  const body = new URLSearchParams();
  for (const control of Array.from(
    form.querySelectorAll("input,select,textarea"),
  )) {
    const name = control.getAttribute("name");
    if (!name || control.hasAttribute("disabled")) continue;
    const type = (control.getAttribute("type") ?? "").toLowerCase();
    if (type === "checkbox" || type === "radio") {
      const checked =
        (control as { checked?: boolean }).checked === true ||
        control.hasAttribute("checked");
      if (checked) body.append(name, control.getAttribute("value") ?? "on");
      continue;
    }
    if (type === "submit" || type === "button") continue;
    body.append(
      name,
      (control as { value?: string }).value ??
        control.getAttribute("value") ??
        "",
    );
  }
  const submitterName = submitter?.getAttribute("name");
  if (submitterName)
    body.append(submitterName, submitter?.getAttribute("value") ?? "");
  return body;
}

export type HttpCeremonyPage = CeremonyPage & {
  goto(url: string): Promise<void>;
  /** Every address the page has been at, for navigation assertions. */
  history(): readonly string[];
};

export function createHttpCeremonyPage(
  options: { maxRedirects?: number; headers?: Record<string, string> } = {},
): HttpCeremonyPage {
  const maxRedirects = options.maxRedirects ?? 10;
  const jar: Jar = new Map();
  const visited: string[] = [];
  let currentUrl = "about:blank";
  let document: Document | undefined;
  let elements: Element[] = [];
  let lastResponse: { status: number; authenticate?: string } | undefined;
  /** Credentials a person entered into the browser's dialog, kept per origin. */
  const dialogCredentials = new Map<string, string>();

  const load = async (
    url: string,
    init: { method: "GET" | "POST"; body?: URLSearchParams },
  ): Promise<void> => {
    let target = url;
    let request = init;
    for (let hop = 0; hop <= maxRedirects; hop++) {
      // Headers the client itself carries, such as a request signature. They
      // belong to the agent's HTTP client, not to any step of the ceremony.
      const headers: Record<string, string> = { ...options.headers };
      const cookies = cookieHeader(jar);
      if (cookies) headers["cookie"] = cookies;
      const dialog = dialogCredentials.get(new URL(target).origin);
      if (dialog) headers["authorization"] = dialog;
      if (request.method === "POST")
        headers["content-type"] = "application/x-www-form-urlencoded";
      const response = await fetch(target, {
        method: request.method,
        redirect: "manual",
        headers,
        ...(request.body ? { body: request.body.toString() } : {}),
      });
      storeCookies(jar, response);
      const location = response.headers.get("location");
      if (response.status >= 300 && response.status < 400 && location) {
        target = new URL(location, target).href;
        request = { method: "GET" };
        continue;
      }
      const html = await response.text();
      const authenticate = response.headers.get("www-authenticate");
      lastResponse = {
        status: response.status,
        ...(authenticate ? { authenticate } : {}),
      };
      currentUrl = target;
      visited.push(target);
      const parsed = parseHTML(html);
      document = parsed.document as unknown as Document;
      // A parsed document has no window location; the snapshot reads it here.
      document.documentElement.setAttribute("data-ceremony-href", currentUrl);
      return;
    }
    throw new Error("Too many redirects");
  };

  const resolve = (element: SnapshotElement): Element => {
    const found = elements[element.index];
    if (!found) throw new Error(`No element at index ${element.index}`);
    return found;
  };

  const submitFrom = async (control: Element): Promise<void> => {
    const form = control.closest("form");
    if (!form) return;
    const method = (form.getAttribute("method") ?? "GET").toUpperCase();
    const action = new URL(
      form.getAttribute("action") ?? currentUrl,
      currentUrl,
    );
    const body = serialize(form, control);
    if (method === "POST") return load(action.href, { method: "POST", body });
    action.search = body.toString();
    return load(action.href, { method: "GET" });
  };

  return {
    goto: (url) => load(url, { method: "GET" }),
    history: () => [...visited],
    url: async () => currentUrl,
    response: async () => lastResponse,
    authenticate: async (origin, credentials) => {
      dialogCredentials.set(
        new URL(origin).origin,
        `Basic ${Buffer.from(`${credentials.username}:${credentials.password}`).toString("base64")}`,
      );
    },
    snapshot: async (): Promise<PageSnapshot> => {
      if (!document) throw new Error("No page has been loaded");
      elements = [];
      return snapshotDocument(document, snapshotSelectors, (element, index) => {
        elements[index] = element;
      });
    },
    fill: async (element, value) => {
      const control = resolve(element);
      control.setAttribute("value", value);
      (control as { value?: string }).value = value;
    },
    check: async (element) => {
      const control = resolve(element);
      control.setAttribute("checked", "checked");
      (control as { checked?: boolean }).checked = true;
    },
    click: async (element) => {
      const control = resolve(element);
      const tag = control.tagName.toLowerCase();
      const href = control.getAttribute("href");
      if (tag === "a" && href)
        return load(new URL(href, currentUrl).href, { method: "GET" });
      return submitFrom(control);
    },
    settle: async () => {
      // Navigation already completed synchronously with the click.
    },
  };
}

import { z } from "zod";

/**
 * Vocabulary shared by an isolated-browser ceremony driver, the inference port
 * that chooses its next action, and the scenario doubles it is tested against.
 *
 * The snapshot is the only description of a provider page any interpreter ever
 * receives. It deliberately excludes secret input values, query strings and raw
 * markup, so an interpreter cannot read an authorization code, a password or a
 * provider DOM it was never permitted to see. Contract tests assert that
 * exclusion; they do not assume it.
 */

/** What the driver is trying to accomplish at a provider. */
export const ceremonyGoals = [
  "sign-in",
  "registration",
  "authorize",
  /**
   * Cause a credential to be issued. The value is displayed for a person to
   * place in a private collector; the ceremony succeeds when the credential
   * exists, not when an agent has read it.
   */
  "obtain-credential",
] as const;
export const ceremonyGoalSchema = z.enum(ceremonyGoals);
export type CeremonyGoal = z.infer<typeof ceremonyGoalSchema>;

/**
 * Values the driver can supply by name. An interpreter selects a role; code
 * substitutes the value. No interpreter is ever given a value to echo back.
 */
export const ceremonyRoles = [
  "email",
  /**
   * A different, unused address. Offered only when the caller really can obtain
   * one, so an interpreter facing "that address is taken" can tell the
   * difference between a recoverable situation and a wall.
   */
  "alternate-email",
  "username",
  "password",
  "password-confirm",
  "display-name",
  "birth-date",
  "verification-code",
  "totp-code",
  "user-code",
] as const;
export const ceremonyRoleSchema = z.enum(ceremonyRoles);
export type CeremonyRole = z.infer<typeof ceremonyRoleSchema>;

/** Roles whose values must never appear in a snapshot, prompt or diagnostic. */
export const secretRoles: readonly CeremonyRole[] = [
  "password",
  "password-confirm",
  "verification-code",
  "totp-code",
];

export const snapshotElementSchema = z
  .object({
    index: z.number().int().nonnegative(),
    kind: z.enum(["input", "button", "link", "checkbox", "select"]),
    type: z.string().max(32).optional(),
    name: z.string().max(128).optional(),
    label: z.string().max(200).optional(),
    placeholder: z.string().max(200).optional(),
    text: z.string().max(200).optional(),
    options: z.array(z.string().max(100)).max(20).optional(),
    required: z.boolean().optional(),
    /** Whether the control already holds a value. Never the value itself. */
    filled: z.boolean().optional(),
    /**
     * Origin this control's form posts to, present only when it differs from
     * the page's own origin. A provider page can target a third party; the
     * driver refuses to enter a secret into such a form.
     */
    submitsTo: z.string().max(200).optional(),
  })
  .strict();
export type SnapshotElement = z.infer<typeof snapshotElementSchema>;

export const pageSnapshotSchema = z
  .object({
    /** Origin and pathname only: query strings carry authorization codes. */
    path: z.string().max(400),
    title: z.string().max(200),
    headings: z.array(z.string().max(200)).max(8),
    alerts: z.array(z.string().max(300)).max(8),
    /** A human challenge (CAPTCHA, proof of personhood) is present. */
    challenge: z.boolean(),
    /**
     * The page asks for a platform authenticator. Detected from the standard
     * `webauthn` autocomplete hint, not guessed from prose.
     */
    passkey: z.boolean(),
    elements: z.array(snapshotElementSchema).max(60),
  })
  .strict();
export type PageSnapshot = z.infer<typeof pageSnapshotSchema>;

/**
 * Why a ceremony cannot continue. Structured so callers and contract tests can
 * assert the specific wall that was hit instead of matching prose.
 */
export const blockedReasons = [
  "human-challenge",
  "credentials-rejected",
  "account-exists",
  "account-missing",
  "consent-denied",
  "provider-error",
  "unsupported-page",
  /** The browser left every origin the ceremony is permitted to act on. */
  "untrusted-origin",
  /** A person was asked to take part and refused. */
  "human-declined",
  /** The step needs an authenticator this browser cannot drive. */
  "passkey-required",
  /** Credentials are demanded by a browser dialog, which has no page to fill. */
  "native-dialog",
] as const;
export const blockedReasonSchema = z.enum(blockedReasons);
export type BlockedReason = z.infer<typeof blockedReasonSchema>;

/**
 * One step. `note` is a public status line shown to a human; the driver rejects
 * any note that reproduces a supplied secret rather than trusting the author.
 */
export const driverActionSchema = z.strictObject({
  action: z.enum(["fill", "click", "check", "wait", "done", "blocked"]),
  element: z.number().int().nonnegative().optional(),
  role: ceremonyRoleSchema.optional(),
  reason: blockedReasonSchema.optional(),
  note: z.string().max(200).optional(),
});
export type DriverAction = z.infer<typeof driverActionSchema>;

export type CeremonyOutcome =
  | { status: "completed"; steps: number; callback?: CeremonyCallback }
  | { status: "blocked"; reason: BlockedReason; steps: number }
  /** The step budget ran out with the ceremony still incomplete. */
  | { status: "exhausted"; steps: number }
  /** Repeated actions stopped changing the page; the driver stops instead of hanging. */
  | { status: "stalled"; steps: number };

/** Redirect parameters captured from the browser, never from a snapshot. */
export type CeremonyCallback = { code: string; state?: string };

/**
 * Steps a transcript can record. `handoff` is the driver's own, never an
 * interpreter's: asking a person to take part is not an inference decision.
 */
export type CeremonyStepAction = DriverAction["action"] | "handoff";

/** One transcript entry. Values are excluded, so this is safe to persist. */
export type CeremonyStep = {
  path: string;
  action: CeremonyStepAction;
  role?: CeremonyRole;
  reason?: BlockedReason;
  note?: string;
};

const alertSelector =
  '[role="alert"],[role="alertdialog"],.alert-danger,.invalid-feedback,.form-error,.error-message,.field-error,[data-error]';
const challengeSelector =
  '[data-captcha],[data-challenge],.g-recaptcha,.h-captcha,.cf-turnstile,iframe[title*="recaptcha" i],iframe[title*="challenge" i],iframe[src*="captcha" i]';
/**
 * The WebAuthn autocomplete hint is a real published signal a page gives for
 * conditional passkey UI, so detecting it is reading the page rather than
 * guessing at its wording.
 */
const passkeySelector =
  '[autocomplete~="webauthn"],[data-webauthn],[data-passkey]';

/**
 * Build a snapshot from a live document.
 *
 * This function must stay self-contained: `createPlaywrightCeremonyPage` ships
 * its source into the page with `evaluate`, so it may not reference anything
 * outside its own body apart from the two selector arguments. It runs unchanged
 * against a real browser DOM and against a parsed document in Node, which is
 * what lets one contract suite cover both.
 */
export function snapshotDocument(
  doc: Document,
  selectors: { alerts: string; challenge: string; passkey: string },
  onElement?: (element: Element, index: number) => void,
): PageSnapshot {
  const trim = (value: string | null | undefined, max: number) =>
    (value ?? "").replace(/\s+/g, " ").trim().slice(0, max);
  const labelFor = (element: Element): string => {
    const aria = trim(element.getAttribute("aria-label"), 200);
    if (aria) return aria;
    const labelledBy = element.getAttribute("aria-labelledby");
    if (labelledBy) {
      const target = doc.getElementById(labelledBy);
      if (target) return trim(target.textContent, 200);
    }
    const id = element.getAttribute("id");
    if (id && /^[A-Za-z][\w:.-]*$/.test(id)) {
      const explicit = doc.querySelector(`label[for="${id}"]`);
      if (explicit) return trim(explicit.textContent, 200);
    }
    const wrapping = element.closest("label");
    if (wrapping) return trim(wrapping.textContent, 200);
    return "";
  };
  /** The page's own address. A document parsed in Node carries it as an attribute. */
  const href =
    doc.defaultView?.location?.href ??
    doc.documentElement.getAttribute("data-ceremony-href") ??
    "";
  let path = "";
  try {
    const here = new URL(href);
    path = `${here.origin}${here.pathname}`;
  } catch {
    path = "";
  }
  const elements: SnapshotElement[] = [];
  const controls = doc.querySelectorAll(
    "input,select,textarea,button,a[href],[role='button'],[role='link']",
  );
  const seen = new Set<Element>();
  for (const control of Array.from(controls)) {
    if (elements.length >= 60) break;
    if (seen.has(control)) continue;
    seen.add(control);
    const style =
      typeof globalThis.getComputedStyle === "function"
        ? globalThis.getComputedStyle(control)
        : undefined;
    if (style && (style.display === "none" || style.visibility === "hidden"))
      continue;
    const tag = control.tagName.toLowerCase();
    const rawType = (control.getAttribute("type") ?? "").toLowerCase();
    if (tag === "input" && rawType === "hidden") continue;
    const label = labelFor(control);
    const name = trim(control.getAttribute("name"), 128);
    const placeholder = trim(control.getAttribute("placeholder"), 200);
    const text = trim(control.textContent, 200);
    const value =
      (control as { value?: string }).value ??
      control.getAttribute("value") ??
      "";
    const checked =
      (control as { checked?: boolean }).checked === true ||
      control.hasAttribute("checked");
    const required =
      control.hasAttribute("required") ||
      control.getAttribute("aria-required") === "true";
    const entry: SnapshotElement = { index: elements.length, kind: "input" };
    if (tag === "input" && (rawType === "checkbox" || rawType === "radio")) {
      entry.kind = "checkbox";
      entry.filled = checked;
    } else if (tag === "select") {
      entry.kind = "select";
      entry.options = Array.from(control.querySelectorAll("option"))
        .slice(0, 20)
        .map((option) => trim(option.textContent, 100));
      entry.filled = value.length > 0;
    } else if (tag === "button" || rawType === "submit" || rawType === "button")
      entry.kind = "button";
    else if (tag === "a" || control.getAttribute("role") === "link")
      entry.kind = "link";
    else {
      entry.kind = "input";
      entry.filled = value.length > 0;
    }
    if (entry.kind === "input" || entry.kind === "checkbox")
      entry.type = rawType || (tag === "textarea" ? "textarea" : "text");
    if (name) entry.name = name;
    if (label) entry.label = label;
    if (placeholder) entry.placeholder = placeholder;
    if (entry.kind === "button" || entry.kind === "link") {
      const caption =
        text ||
        label ||
        trim(control.getAttribute("value"), 200) ||
        trim(control.getAttribute("title"), 200);
      if (caption) entry.text = caption;
    }
    if (required) entry.required = true;
    const action = control.closest("form")?.getAttribute("action");
    if (action) {
      try {
        const target = new URL(action, href);
        if (target.origin !== new URL(href).origin)
          entry.submitsTo = target.origin;
      } catch {
        entry.submitsTo = "unknown";
      }
    }
    if (onElement) onElement(control, entry.index);
    elements.push(entry);
  }
  const headings = Array.from(doc.querySelectorAll("h1,h2,h3,legend"))
    .slice(0, 8)
    .map((heading) => trim(heading.textContent, 200))
    .filter((heading) => heading.length > 0);
  const alerts = Array.from(doc.querySelectorAll(selectors.alerts))
    .slice(0, 8)
    .map((alert) => trim(alert.textContent, 300))
    .filter((alert) => alert.length > 0);
  return {
    path,
    title: trim(doc.title, 200),
    headings,
    alerts,
    challenge: doc.querySelector(selectors.challenge) !== null,
    passkey: doc.querySelector(selectors.passkey) !== null,
    elements,
  };
}

/** Selector arguments for {@link snapshotDocument}, shared by every adapter. */
export const snapshotSelectors = {
  alerts: alertSelector,
  challenge: challengeSelector,
  passkey: passkeySelector,
} as const;

/**
 * Source that evaluates {@link snapshotDocument} inside a live page and stamps
 * each captured element with its index, so a later action addresses exactly the
 * element the interpreter saw.
 *
 * The function is shipped as text, which means it arrives compiled. A compiler
 * that preserves function names — esbuild's `keepNames`, which tsx turns on —
 * emits calls to a `__name` helper that exists in the bundle but not in the
 * page, so the shim is supplied alongside it. Without that, whether the
 * snapshot works at all depends on which tool compiled the caller.
 */
export function snapshotPageSource(indexAttribute: string): string {
  return `(() => {
    const __name = (value) => value;
    for (const stale of document.querySelectorAll('[${indexAttribute}]'))
      stale.removeAttribute('${indexAttribute}');
    const snapshot = ${snapshotDocument.toString()};
    return snapshot(document, ${JSON.stringify(snapshotSelectors)}, (element, index) =>
      element.setAttribute('${indexAttribute}', String(index)));
  })()`;
}

import { z } from "zod";

export const identifierSchema = z
