/**
 * Seeded page-shape randomization for the auth scenario doubles.
 *
 * Every instance of the provider double invents its own field names, label
 * wording, label association style, control order, button captions, alert
 * markup and signup path. A driver therefore cannot pass by recognising a fixed
 * page: it has to work from the semantics the snapshot actually carries. The
 * seed makes a failure reproducible, so a broken case can be replayed exactly.
 */

/** Stable 32-bit hash so a page's shape derives from its name, not call order. */
export function hashKey(value: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index++) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

export function seededRandom(seed: number): () => number {
  let state = seed >>> 0 || 0x9e3779b9;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

const pools = {
  identifier: ["Username", "Handle", "Login name", "Account name"],
  email: ["Email", "E-mail address", "Email address", "Your email"],
  password: ["Password", "Choose a password", "Passphrase", "Your password"],
  confirm: ["Confirm password", "Repeat password", "Password again"],
  displayName: ["Display name", "Your name", "Full name"],
  birthDate: ["Date of birth", "Birth date", "Your birthday"],
  terms: [
    "I agree to the Terms of Service",
    "I accept the terms and the privacy policy",
    "I confirm I am old enough to use this service",
  ],
  verification: ["Confirmation code", "Verification code", "6-digit code"],
  totp: ["Authenticator code", "One-time code", "Two-factor code"],
  userCode: ["Device code", "Pairing code", "Code shown on your device"],
  signIn: ["Sign in", "Log in", "Continue", "Next"],
  signUp: ["Create account", "Register", "Sign up", "Join"],
  submitCode: ["Confirm", "Verify", "Submit code", "Continue"],
  approve: ["Authorize", "Allow", "Approve", "Grant access"],
  deny: ["Deny", "Cancel", "Not now"],
  resend: ["Resend confirmation", "Send a new link", "Email me again"],
  signUpLink: ["Create an account", "Sign up", "Register here", "Join now"],
  signInHeading: ["Welcome back", "Sign in to continue", "Account access"],
  signUpHeading: ["Create your account", "Join us", "Registration"],
  consentHeading: ["Authorize this application", "Allow access?", "Consent"],
  alert: [
    'role="alert"',
    'class="alert-danger"',
    'class="invalid-feedback"',
    'class="form-error"',
    'class="error-message"',
  ],
  signupPath: ["/signup", "/register", "/join", "/account/create", "/auth/new"],
  emailInUse: [
    "That email address is already in use.",
    "An account with this address already exists.",
    "This email is taken. Try signing in instead.",
  ],
  rejected: [
    "We could not sign you in with those details.",
    "Incorrect username or password.",
    "Those credentials were not accepted.",
  ],
  unverified: [
    "Confirm your email address before signing in.",
    "This account is not verified yet.",
  ],
  mismatch: ["The passwords do not match.", "Both passwords must be the same."],
  termsRequired: [
    "You must accept the terms to continue.",
    "Please agree to the terms first.",
  ],
  badCode: ["That code is not correct.", "The code you entered did not match."],
  checkInbox: [
    "Check your inbox to confirm the account.",
    "We sent you a confirmation message.",
  ],
} as const;

export type Markup = ReturnType<typeof createMarkup>;

export function createMarkup(seed: number) {
  const random = seededRandom(seed);
  const pick = <T>(items: readonly T[]): T =>
    items[Math.floor(random() * items.length)]!;
  const token = () => Math.floor(random() * 0xffffff).toString(36);
  /**
   * Order a page's controls. The permutation comes from the instance seed and
   * the page's own name, so a given seed renders a given page identically every
   * time it is requested — a fixture whose shape drifted between renders could
   * not be replayed from its seed.
   */
  const arrange = <T>(key: string, items: readonly T[]): T[] => {
    const local = seededRandom(
      (seed ^ hashKey(key) ^ (items.length << 16)) >>> 0,
    );
    const copy = [...items];
    for (let index = copy.length - 1; index > 0; index--) {
      const swap = Math.floor(local() * (index + 1));
      [copy[index], copy[swap]] = [copy[swap]!, copy[index]!];
    }
    return copy;
  };

  const names = {
    identifier: `u_${token()}`,
    email: `e_${token()}`,
    password: `p_${token()}`,
    confirm: `c_${token()}`,
    displayName: `n_${token()}`,
    birthDate: `b_${token()}`,
    terms: `t_${token()}`,
    code: `v_${token()}`,
    userCode: `d_${token()}`,
  } as const;

  const labels = {
    identifier: pick(pools.identifier),
    email: pick(pools.email),
    password: pick(pools.password),
    confirm: pick(pools.confirm),
    displayName: pick(pools.displayName),
    birthDate: pick(pools.birthDate),
    terms: pick(pools.terms),
    verification: pick(pools.verification),
    totp: pick(pools.totp),
    userCode: pick(pools.userCode),
  } as const;

  const captions = {
    signIn: pick(pools.signIn),
    signUp: pick(pools.signUp),
    submitCode: pick(pools.submitCode),
    approve: pick(pools.approve),
    deny: pick(pools.deny),
    resend: pick(pools.resend),
    signUpLink: pick(pools.signUpLink),
  } as const;

  const messages = {
    emailInUse: pick(pools.emailInUse),
    rejected: pick(pools.rejected),
    unverified: pick(pools.unverified),
    mismatch: pick(pools.mismatch),
    termsRequired: pick(pools.termsRequired),
    badCode: pick(pools.badCode),
    checkInbox: pick(pools.checkInbox),
  } as const;

  const alertAttribute = pick(pools.alert);
  const signupPath = pick(pools.signupPath);
  const includeDisplayName = random() > 0.4;
  const includeBirthDate = random() > 0.5;
  /** A provider that does not use type="email" forces label-based reasoning. */
  const emailInputType = random() > 0.5 ? "email" : "text";

  const escape = (value: string) =>
    value.replace(
      /[&<>"]/g,
      (character) =>
        ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[
          character
        ] as string,
    );

  /** Render one control, varying how its accessible name is attached. */
  const field = (
    label: string,
    name: string,
    type: string,
    attributes = "",
  ): string => {
    const id = `field_${name}`;
    // Derived from the field's own name for the same reason `arrange` is.
    const style = Math.floor(seededRandom((seed ^ hashKey(name)) >>> 0)() * 4);
    const input = `<input id="${id}" name="${name}" type="${type}" ${attributes}>`;
    if (style === 0)
      return `<p><label for="${id}">${escape(label)}</label>${input}</p>`;
    if (style === 1)
      return `<p><input id="${id}" name="${name}" type="${type}" aria-label="${escape(label)}" ${attributes}></p>`;
    if (style === 2)
      return `<p><input id="${id}" name="${name}" type="${type}" placeholder="${escape(label)}" ${attributes}></p>`;
    return `<p><label>${escape(label)} ${input}</label></p>`;
  };

  const checkbox = (label: string, name: string): string =>
    `<p><label><input name="${name}" type="checkbox" value="yes"> ${escape(label)}</label></p>`;

  const alert = (message?: string): string =>
    message ? `<div ${alertAttribute}>${escape(message)}</div>` : "";

  const page = (title: string, body: string): string =>
    `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${escape(title)}</title></head><body>${body}</body></html>`;

  return {
    seed,
    names,
    labels,
    captions,
    messages,
    signupPath,
    includeDisplayName,
    includeBirthDate,
    emailInputType,
    headings: {
      signIn: pick(pools.signInHeading),
      signUp: pick(pools.signUpHeading),
      consent: pick(pools.consentHeading),
    },
    escape,
    field,
    checkbox,
    alert,
    page,
    arrange,
  };
}

import {
  createHash,
  createPublicKey,
  generateKeyPairSync,
  sign as signBytes,
  verify as verifyBytes,
  type KeyObject,
} from "node:crypto";
import { createServer, type Server } from "node:http";
import type { AddressInfo } from "node:net";

/**
 * Signed agent identity, as `draft-meunier-webbotauth-httpsig-protocol-02`
 * describes it.
 *
 * An agent signs its own requests with an Ed25519 key and publishes the public
 * half at a well-known directory; the origin fetches that directory and checks
 * the signature before deciding whether it is talking to a bot it knows. This
 * is not an authentication method in the sense the rest of the catalog uses —
 * it says nothing about which user is present — so it is modelled as a gate in
 * front of an ordinary ceremony rather than as a flow of its own.
 *
 * One signature covers `@authority` only. The draft requires at least one of
 * `@authority` or `@target-uri`, and covering the authority means a single
 * signature stays valid for every request to that host until it expires, which
 * is what lets a browser carry it as an ordinary header for a whole ceremony.
 */

const base64url = (value: Buffer) => value.toString("base64url");

export type SignatureKey = {
  privateKey: KeyObject;
  publicKey: KeyObject;
  /** RFC 7638 JWK thumbprint, which is the `keyid` the draft requires. */
  keyId: string;
  jwk: { kty: "OKP"; crv: "Ed25519"; x: string };
};

export function createSignatureKey(): SignatureKey {
  const { privateKey, publicKey } = generateKeyPairSync("ed25519");
  const exported = publicKey.export({ format: "jwk" }) as { x: string };
  const jwk = { kty: "OKP", crv: "Ed25519", x: exported.x } as const;
  // The thumbprint is taken over the required members in lexicographic order
  // with no whitespace, which for an OKP key is crv, kty, x.
  const canonical = JSON.stringify({ crv: jwk.crv, kty: jwk.kty, x: jwk.x });
  return {
    privateKey,
    publicKey,
    keyId: base64url(createHash("sha256").update(canonical).digest()),
    jwk,
  };
}

export type SignatureOptions = {
  /** Seconds until the signature expires. The draft recommends at most 24h. */
  lifetimeSeconds?: number;
  /** Seconds to shift `created`, to produce one that has already lapsed. */
  ageSeconds?: number;
  /** Overrides the `web-bot-auth` tag, to produce one an origin discards. */
  tag?: string;
  /** Sign with a key the directory does not publish. */
  signWith?: KeyObject;
};

/**
 * The signature base of RFC 9421: one line per covered component, then the
 * signature parameters, with no trailing newline.
 */
function signatureBase(authority: string, params: string): string {
  return `"@authority": ${authority}\n"@signature-params": ${params}`;
}

/**
 * Headers an agent adds to every request to `authority`, proving which bot it
 * is. `directory` is where the origin will look for the public key.
 */
export function signRequestHeaders(
  key: SignatureKey,
  authority: string,
  directory: string,
  options: SignatureOptions = {},
): Record<string, string> {
  const now = Math.floor(Date.now() / 1000) - (options.ageSeconds ?? 0);
  const created = now;
  const expires = created + (options.lifetimeSeconds ?? 300);
  const params =
    `("@authority");created=${created};expires=${expires};` +
    `keyid="${key.keyId}";alg="ed25519";tag="${options.tag ?? "web-bot-auth"}"`;
  const signature = signBytes(
    null,
    Buffer.from(signatureBase(authority, params), "utf8"),
    options.signWith ?? key.privateKey,
  );
  return {
    "signature-input": `sig=${params}`,
    signature: `sig=:${signature.toString("base64")}:`,
    "signature-agent": `sig="${directory}";type=directory`,
  };
}

export type SignatureVerdict =
  | { ok: true; keyId: string }
  | {
      ok: false;
      why:
        | "absent"
        | "malformed"
        | "untagged"
        | "expired"
        | "unknown-key"
        | "bad-signature"
        | "no-directory";
    };

/** Parse `sig=(...);a=b;c="d"` into its covered components and parameters. */
function parseSignatureInput(
  header: string,
):
  | { components: string[]; params: Record<string, string>; raw: string }
  | undefined {
  const match = /^[^=]+=(\(([^)]*)\)(.*))$/.exec(header.trim());
  if (!match) return undefined;
  const components = (match[2] ?? "")
    .split(/\s+/)
    .filter(Boolean)
    .map((entry) => entry.replace(/^"|"$/g, ""));
  const params: Record<string, string> = {};
  for (const part of (match[3] ?? "").split(";")) {
    const pair = /^([a-z]+)=(.*)$/.exec(part.trim());
    if (pair?.[1] && pair[2] !== undefined)
      params[pair[1]] = pair[2].replace(/^"|"$/g, "");
  }
  return { components, params, raw: match[1] ?? "" };
}

/**
 * Verify a request's signature the way an origin would: read the agent's
 * directory, find the key the signature names, and check it over the base the
 * signature says it covers. Every refusal names its own reason, because "403"
 * on its own tells an agent nothing about what to fix.
 */
export async function verifyRequestSignature(
  headers: Record<string, string | string[] | undefined>,
  authority: string,
  options: { fetchDirectory?: typeof fetch } = {},
): Promise<SignatureVerdict> {
  const single = (name: string) => {
    const value = headers[name];
    return Array.isArray(value) ? value[0] : value;
  };
  const input = single("signature-input");
  const signature = single("signature");
  const agent = single("signature-agent");
  if (!input || !signature) return { ok: false, why: "absent" };
  const parsed = parseSignatureInput(input);
  if (!parsed) return { ok: false, why: "malformed" };
  // A signature that is not tagged for this purpose is not for us to act on.
  if (parsed.params["tag"] !== "web-bot-auth")
    return { ok: false, why: "untagged" };
  const created = Number(parsed.params["created"]);
  const expires = Number(parsed.params["expires"]);
  if (!Number.isFinite(created) || !Number.isFinite(expires))
    return { ok: false, why: "malformed" };
  // At least one of these must be covered, or the signature says nothing about
  // where the request was going.
  if (!parsed.components.some((name) => name === "@authority"))
    return { ok: false, why: "malformed" };
  const now = Math.floor(Date.now() / 1000);
  if (now >= expires || created > now + 5) return { ok: false, why: "expired" };
  const directory = /"([^"]+)"/.exec(agent ?? "")?.[1];
  if (!directory) return { ok: false, why: "no-directory" };

  const get = options.fetchDirectory ?? fetch;
  let keys: { x?: string; kty?: string; crv?: string }[];
  try {
    const response = await get(
      `${directory}/.well-known/http-message-signatures-directory`,
      { redirect: "error" },
    );
    // The draft is explicit: anything but 200 is a discovery failure, and a
    // verifier must not follow redirects to find one.
    if (response.status !== 200) return { ok: false, why: "no-directory" };
    keys = ((await response.json()) as { keys?: unknown[] }).keys as never[];
  } catch {
    return { ok: false, why: "no-directory" };
  }
  if (!Array.isArray(keys)) return { ok: false, why: "no-directory" };

  const keyId = parsed.params["keyid"] ?? "";
  const published = keys.find((jwk) => {
    if (jwk.kty !== "OKP" || jwk.crv !== "Ed25519" || !jwk.x) return false;
    const canonical = JSON.stringify({ crv: jwk.crv, kty: jwk.kty, x: jwk.x });
    return base64url(createHash("sha256").update(canonical).digest()) === keyId;
  });
  if (!published) return { ok: false, why: "unknown-key" };

  const raw = /:([^:]*):/.exec(signature)?.[1];
  if (!raw) return { ok: false, why: "malformed" };
  const verified = verifyBytes(
    null,
    Buffer.from(signatureBase(authority, parsed.raw), "utf8"),
    createPublicKey({ key: published as never, format: "jwk" }),
    Buffer.from(raw, "base64"),
  );
  return verified ? { ok: true, keyId } : { ok: false, why: "bad-signature" };
}

/**
 * The agent's published key directory. A real one belongs to whoever operates
 * the bot, not to the site being visited, so it is a separate origin here too.
 */
export async function startSignatureDirectory(
  keys: readonly SignatureKey[],
  options: { status?: number } = {},
): Promise<{ origin: string; reads(): number; close(): Promise<void> }> {
  let reads = 0;
  const server: Server = createServer((request, response) => {
    if (
      request.url !== "/.well-known/http-message-signatures-directory" ||
      request.method !== "GET"
    ) {
      response.writeHead(404).end();
      return;
    }
    reads += 1;
    response.writeHead(options.status ?? 200, {
      "content-type": "application/http-message-signatures-directory+json",
    });
    response.end(JSON.stringify({ keys: keys.map((key) => key.jwk) }));
  });
  await new Promise<void>((resolve) =>
    server.listen(0, "127.0.0.1", () => resolve()),
  );
  const { port } = server.address() as AddressInfo;
  let shut = false;
  return {
    origin: `http://127.0.0.1:${port}`,
    reads: () => reads,
    close: async () => {
      if (shut) return;
      shut = true;
      server.closeAllConnections();
      await new Promise<void>((resolve, reject) =>
        server.close((error) => (error ? reject(error) : resolve())),
      );
    },
  };
}

/** Present only so a caller can sign with a key the directory never lists. */
export function unpublishedKey(): KeyObject {
  return generateKeyPairSync("ed25519").privateKey;
}
